package com.banktaggearbuilder;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BankTagGearBuilderConfig.GROUP)
public interface BankTagGearBuilderConfig extends Config
{
	String GROUP = "bank-tag-gear-builder";

	enum OutputMode
	{
		ASK("Ask each time"),
		CREATE_TAG("Create tag automatically"),
		COPY_IMPORT_STRING("Copy import string");

		private final String label;

		OutputMode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum TagNaming
	{
		CONTENT_AND_STYLE("Content + style"),
		CONTENT("Content name");

		private final String label;

		TagNaming(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "outputMode",
		name = "Output",
		description = "What to do with a built setup: create the Bank Tags tag, copy an import string, or show both options",
		position = 1
	)
	default OutputMode outputMode()
	{
		return OutputMode.ASK;
	}

	@ConfigItem(
		keyName = "includeInventory",
		name = "Include inventory items",
		description = "Add the wiki's recommended inventory (potions, food, runes, teleports) to the tag",
		position = 3
	)
	default boolean includeInventory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "matchEquippedAndInventory",
		name = "Count equipped and inventory items",
		description = "Treat items you are wearing or carrying as owned, not only items in the bank",
		position = 4
	)
	default boolean matchEquippedAndInventory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tagNaming",
		name = "Tag naming",
		description = "Name tags after the content only, or the content and the setup style (e.g. 'vorkath - ranged')",
		position = 5
	)
	default TagNaming tagNaming()
	{
		return TagNaming.CONTENT_AND_STYLE;
	}

	@ConfigItem(
		keyName = "arrangeBySlot",
		name = "Arrange items by slot",
		description = "Give created tags a Bank Tags layout shaped like the equipment screen, with special attack weapons beside it and inventory items on the rows below",
		position = 6
	)
	default boolean arrangeBySlot()
	{
		return true;
	}
}

package com.banktaggearbuilder;

import com.banktaggearbuilder.model.BuildResult;
import com.banktaggearbuilder.model.ContentPage;
import com.banktaggearbuilder.model.GearSetup;
import com.banktaggearbuilder.model.GeneratedTag;
import com.banktaggearbuilder.model.StrategyPage;
import com.banktaggearbuilder.model.TagStatus;
import com.banktaggearbuilder.ui.GearBuilderPanel;
import com.banktaggearbuilder.wiki.WikiClient;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Bank Tag Gear Builder",
	description = "Builds a Bank Tags tag for a boss or activity from the OSRS Wiki's recommended gear, using only items you own",
	tags = {"bank", "tags", "gear", "equipment", "setup", "loadout", "wiki", "boss"},
	internalName = "bank-tag-gear-builder"
)
@PluginDependency(BankTagsPlugin.class)
public class BankTagGearBuilderPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private BankTagGearBuilderConfig config;

	@Inject
	private WikiClient wikiClient;

	@Inject
	private ItemNameIndex itemNameIndex;

	@Inject
	private OwnedItems ownedItems;

	@Inject
	private GearMatcher matcher;

	@Inject
	private BankTagWriter writer;

	@Inject
	private GeneratedTagStore store;

	/** RS-profile config key holding the cached bank, so each account keeps its own. */
	private static final String BANK_CACHE_KEY = "bankCache";

	@Inject
	private ConfigManager configManager;

	private GearBuilderPanel panel;
	private NavigationButton navButton;
	/** Set once a bank cache lookup found a profile to read from, so ticks stop retrying. */
	private boolean bankCacheChecked;

	/** Tags this plugin created. Only touched on the client thread after startUp. */
	private final List<GeneratedTag> generated = new ArrayList<>();
	/** Result of the last Build per existing tag, waiting for the player to apply it. */
	private final Map<String, BuildResult> pendingBuilds = new LinkedHashMap<>();

	@Override
	protected void startUp()
	{
		try
		{
			wikiClient.setCacheDirectory(getPluginDirectory().joinSegment("wiki-cache"));
		}
		catch (IOException e)
		{
			log.debug("No plugin directory available; wiki responses will not be cached", e);
		}

		panel = new GearBuilderPanel(this, itemManager, config);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Bank Tag Gear Builder")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invoke(() ->
		{
			generated.clear();
			generated.addAll(store.loadAll());
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				itemNameIndex.ensureBuilt(this::recheckAll);
				ownedItems.update(InventoryID.INV, client.getItemContainer(InventoryID.INV));
				ownedItems.update(InventoryID.WORN, client.getItemContainer(InventoryID.WORN));
			}
			recheckAll();
		});
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		ownedItems.clear();
		pendingBuilds.clear();
	}

	@Provides
	BankTagGearBuilderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankTagGearBuilderConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			bankCacheChecked = false;
			itemNameIndex.ensureBuilt(this::recheckAll);
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			ownedItems.clear();
			bankCacheChecked = false;
			recheckAll();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The RS profile can become available a little after LOGGED_IN; keep trying until it does
		if (!bankCacheChecked && !ownedItems.isBankSeen())
		{
			loadBankCache();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		boolean firstBankSight = event.getContainerId() == InventoryID.BANK
			&& (!ownedItems.isBankSeen() || ownedItems.isBankFromCache());
		if (ownedItems.update(event.getContainerId(), event.getItemContainer()) && firstBankSight)
		{
			saveBankCache();
			recheckAll();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			saveBankCache();
		}
	}

	private void saveBankCache()
	{
		if (!ownedItems.isBankSeen() || ownedItems.isBankFromCache() || configManager.getRSProfileKey() == null)
		{
			return;
		}
		configManager.setRSProfileConfiguration(BankTagGearBuilderConfig.GROUP, BANK_CACHE_KEY, ownedItems.serializeBank());
	}

	/**
	 * @return true if the bank is known, live or from cache
	 */
	private boolean loadBankCache()
	{
		if (ownedItems.isBankSeen())
		{
			return true;
		}
		if (client.getGameState() != GameState.LOGGED_IN || configManager.getRSProfileKey() == null)
		{
			return false;
		}
		bankCacheChecked = true;
		String cached = configManager.getRSProfileConfiguration(BankTagGearBuilderConfig.GROUP, BANK_CACHE_KEY);
		if (ownedItems.loadBank(cached))
		{
			log.debug("Loaded bank cache saved at {}", ownedItems.getCacheSavedAt());
			recheckAll();
			return true;
		}
		return false;
	}

	public boolean isBankFromCache()
	{
		return ownedItems.isBankFromCache();
	}

	public long getBankCacheSavedAt()
	{
		return ownedItems.getCacheSavedAt();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Ignore our own tag_ and bank cache writes, otherwise every save would trigger another re-check
		if (BankTagGearBuilderConfig.GROUP.equals(event.getGroup())
			&& !event.getKey().startsWith(GeneratedTagStore.KEY_PREFIX)
			&& !event.getKey().equals(BANK_CACHE_KEY))
		{
			clientThread.invoke(this::recheckAll);
			GearBuilderPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(p::onConfigChanged);
			}
		}
	}

	// ---- Called from the side panel (Swing thread). Callbacks are delivered on the Swing thread. ----

	/**
	 * @param force skip the cached list and download it from the wiki, replacing the cache
	 */
	public void loadContent(boolean force, Consumer<List<ContentPage>> onSuccess, Consumer<String> onError)
	{
		wikiClient.listContent(force,
			pages -> SwingUtilities.invokeLater(() -> onSuccess.accept(pages)),
			err -> SwingUtilities.invokeLater(() -> onError.accept(err)));
	}

	/**
	 * @param force skip the cached copy and download the page from the wiki, replacing the cache
	 */
	public void fetchStrategy(ContentPage page, boolean force, Consumer<StrategyPage> onSuccess, Consumer<String> onError)
	{
		wikiClient.fetchStrategy(page, force,
			sp -> SwingUtilities.invokeLater(() -> onSuccess.accept(sp)),
			err -> SwingUtilities.invokeLater(() -> onError.accept(err)));
	}

	public boolean isBankSeen()
	{
		return ownedItems.isBankSeen();
	}

	public boolean isLoggedIn()
	{
		return client.getGameState() == GameState.LOGGED_IN;
	}

	public void build(ContentPage page, GearSetup setup, Consumer<BuildResult> onResult)
	{
		itemNameIndex.ensureBuilt(() ->
		{
			BuildResult result = matcher.match(setup, config.matchEquippedAndInventory(), config.includeInventory());
			// If this setup already has a tag, offer the built result as its pending update
			String tag = tagNameFor(page, setup);
			if (findGenerated(tag) != null)
			{
				pendingBuilds.put(tag, result);
			}
			recheckAll();
			SwingUtilities.invokeLater(() -> onResult.accept(result));
		});
	}

	/**
	 * Writes the pending Build result for this tag. Nothing is re-scanned: the result the
	 * player saw in the panel is exactly what gets applied.
	 */
	public void applyUpdate(String tag)
	{
		clientThread.invoke(() ->
		{
			GeneratedTag g = findGenerated(tag);
			BuildResult result = pendingBuilds.get(tag);
			if (g == null || result == null)
			{
				return;
			}
			List<String> changes = diff(g, result);
			applyResult(g, result, g.getItemIds());
			pendingBuilds.remove(tag);
			chat("Updated tag tab '" + g.getTag() + "'" + (changes.isEmpty() ? "." : ": " + String.join("; ", changes)));
			recheckAll();
		});
	}

	/** Whether a generated tag with this name already exists. Safe from any thread. */
	public boolean hasGeneratedTag(String tag)
	{
		for (GeneratedTag g : new ArrayList<>(generated))
		{
			if (g.getTag().equals(tag))
			{
				return true;
			}
		}
		return false;
	}

	public String tagNameFor(ContentPage page, GearSetup setup)
	{
		String name = page.getDisplayName();
		if (config.tagNaming() == BankTagGearBuilderConfig.TagNaming.CONTENT_AND_STYLE && !setup.getStyle().isEmpty())
		{
			name += " - " + setup.getStyle();
		}
		return BankTagWriter.sanitizeTagName(name);
	}

	public void createTag(StrategyPage page, GearSetup setup, BuildResult result, Consumer<String> onDone)
	{
		String tag = tagNameFor(page.getPage(), setup);
		clientThread.invoke(() ->
		{
			GeneratedTag existing = findGenerated(tag);
			GeneratedTag g = existing != null ? existing : new GeneratedTag();
			g.setTag(tag);
			g.setPageTitle(page.getPage().getTitle());
			g.setDisplayName(page.getPage().getDisplayName());
			g.setStyle(setup.getStyle());
			g.setRevId(page.getRevId());
			g.setFetchedAt(page.getFetchedAt());
			g.setSetup(setup);
			List<String> changes = existing != null ? diff(existing, result) : Collections.emptyList();
			applyResult(g, result, existing != null ? existing.getItemIds() : null);
			pendingBuilds.remove(tag);
			if (existing == null)
			{
				generated.add(g);
				chat("Created tag tab '" + tag + "' with " + result.getTagItemIds().size() + " items."
					+ (writer.isBankOpen() ? " It is open now; the tab appears in the strip next time you open the bank." : ""));
			}
			else
			{
				chat("Updated tag tab '" + tag + "'" + (changes.isEmpty() ? "." : ": " + String.join("; ", changes)));
			}
			recheckAll();
			SwingUtilities.invokeLater(() -> onDone.accept(tag));
		});
	}


	public void removeGenerated(String tag, boolean deleteBankTag)
	{
		clientThread.invoke(() ->
		{
			GeneratedTag g = findGenerated(tag);
			if (g == null)
			{
				return;
			}
			if (deleteBankTag)
			{
				writer.deleteTag(g.getTag());
			}
			store.remove(g.getTag());
			generated.remove(g);
			pendingBuilds.remove(g.getTag());
			recheckAll();
		});
	}

	/**
	 * Re-fetches every generated tag's wiki page, replacing the stored setup if the page changed,
	 * then re-checks all tags.
	 */
	public void refreshSources(Consumer<String> onStatus)
	{
		clientThread.invoke(() ->
		{
			if (generated.isEmpty())
			{
				SwingUtilities.invokeLater(() -> onStatus.accept("No generated tags to refresh."));
				return;
			}
			List<GeneratedTag> snapshot = new ArrayList<>(generated);
			AtomicInteger remaining = new AtomicInteger(snapshot.size());
			AtomicInteger changed = new AtomicInteger();
			Runnable finish = () ->
			{
				if (remaining.decrementAndGet() == 0)
				{
					int n = changed.get();
					clientThread.invoke(this::recheckAll);
					SwingUtilities.invokeLater(() -> onStatus.accept(n == 0 ? "All wiki pages unchanged." : n + " wiki page(s) changed."));
				}
			};
			for (GeneratedTag g : snapshot)
			{
				// Explicit refresh: bypass the cache so a changed wiki page is noticed
				wikiClient.fetchStrategy(new ContentPage(g.getPageTitle()), true, sp -> clientThread.invoke(() ->
				{
					if (sp.getRevId() != g.getRevId())
					{
						GearSetup match = pickSetup(sp.getSetups(), g.getStyle());
						g.setSetup(match);
						g.setStyle(match.getStyle());
						g.setRevId(sp.getRevId());
						g.setFetchedAt(sp.getFetchedAt());
						g.setSourceChanged(true);
						store.save(g);
						changed.incrementAndGet();
					}
					finish.run();
				}), err ->
				{
					log.debug("Refresh failed for {}: {}", g.getPageTitle(), err);
					finish.run();
				});
			}
		});
	}

	// ---- Client thread ----

	private GeneratedTag findGenerated(String tag)
	{
		for (GeneratedTag g : generated)
		{
			if (g.getTag().equals(tag))
			{
				return g;
			}
		}
		return null;
	}

	private static GearSetup pickSetup(List<GearSetup> setups, String style)
	{
		String want = style == null ? "" : style.toLowerCase(Locale.ROOT);
		for (GearSetup s : setups)
		{
			if (s.getStyle().toLowerCase(Locale.ROOT).equals(want))
			{
				return s;
			}
		}
		return setups.get(0);
	}

	private void applyResult(GeneratedTag g, BuildResult result, List<Integer> previousItemIds)
	{
		List<Integer> ids = result.getTagItemIds();
		Set<Integer> exact = result.getExactItemIds();
		int icon = result.getIconItemId() > 0 ? result.getIconItemId() : g.getIconItemId();
		writer.writeTag(g.getTag(), ids, exact, icon, previousItemIds, config.arrangeBySlot(), result);
		g.setItemIds(ids);
		g.setExactItemIds(new ArrayList<>(exact));
		g.setIconItemId(icon);
		Map<String, String> picks = new LinkedHashMap<>();
		GearMatcher.summarize(result, picks);
		for (BuildResult.InventoryPick pick : result.getInventory())
		{
			picks.put("inv:" + pick.getName(), pick.getName());
		}
		for (BuildResult.InventoryPick pick : result.getRunePouch())
		{
			picks.put("rune:" + pick.getName(), pick.getName());
		}
		g.setPicks(picks);
		g.setSourceChanged(false);
		store.save(g);
	}

	/**
	 * Human readable differences between what the tag holds and what the bank now supports.
	 */
	private static List<String> diff(GeneratedTag g, BuildResult result)
	{
		List<String> changes = new ArrayList<>();
		Map<String, String> now = new LinkedHashMap<>();
		GearMatcher.summarize(result, now);
		Map<String, String> before = g.getPicks() == null ? Collections.emptyMap() : g.getPicks();

		Set<String> slots = new LinkedHashSet<>();
		for (String k : before.keySet())
		{
			if (!k.startsWith("inv:") && !k.startsWith("rune:"))
			{
				slots.add(k);
			}
		}
		slots.addAll(now.keySet());
		for (String slot : slots)
		{
			String old = before.get(slot);
			String cur = now.get(slot);
			if (old == null && cur != null)
			{
				changes.add(slot + ": " + cur + " added");
			}
			else if (old != null && cur == null)
			{
				changes.add(slot + ": " + old + " no longer owned");
			}
			else if (old != null && !old.equals(cur))
			{
				changes.add(slot + ": " + cur + " replaced " + old);
			}
		}

		diffNamed(changes, "inv:", "Inventory", before, result.getInventory());
		diffNamed(changes, "rune:", "Rune pouch", before, result.getRunePouch());
		return changes;
	}

	private static void diffNamed(List<String> changes, String prefix, String label, Map<String, String> before, List<BuildResult.InventoryPick> now)
	{
		Set<String> old = new LinkedHashSet<>();
		for (String k : before.keySet())
		{
			if (k.startsWith(prefix))
			{
				old.add(k.substring(prefix.length()));
			}
		}
		Set<String> cur = new LinkedHashSet<>();
		for (BuildResult.InventoryPick pick : now)
		{
			cur.add(pick.getName());
		}
		for (String name : cur)
		{
			if (!old.contains(name))
			{
				changes.add(label + ": " + name + " added");
			}
		}
		for (String name : old)
		{
			if (!cur.contains(name))
			{
				changes.add(label + ": " + name + " removed");
			}
		}
	}

	/**
	 * Refreshes the generated-tag list in the panel. Tags are never re-matched here: a tag only
	 * changes through Build followed by "Update tag" or "Apply update", so the player's bank,
	 * inventory and trades never alter a tab behind their back.
	 */
	private void recheckAll()
	{
		if (!ownedItems.isBankSeen() && !bankCacheChecked && client.getGameState() == GameState.LOGGED_IN && configManager.getRSProfileKey() != null)
		{
			// loadBankCache re-enters recheckAll when a cache is found
			if (loadBankCache())
			{
				return;
			}
		}

		List<TagStatus> statuses = new ArrayList<>();
		for (GeneratedTag g : generated)
		{
			Set<Integer> current = new HashSet<>(writer.currentItems(g.getTag()));
			boolean userEdited = !current.equals(new HashSet<>(g.getItemIds()));
			BuildResult pending = pendingBuilds.get(g.getTag());
			List<String> changes = pending != null ? diff(g, pending) : Collections.emptyList();
			if (pending != null && changes.isEmpty())
			{
				// Built the same thing the tag already holds; nothing to offer
				pendingBuilds.remove(g.getTag());
				pending = null;
			}
			statuses.add(new TagStatus(g, pending, userEdited, changes));
		}

		GearBuilderPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.setStatuses(statuses));
		}
	}

	private void chat(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append("Gear Builder: ")
				.append(ChatColorType.NORMAL)
				.append(message)
				.build())
			.build());
	}
}

package com.banktaggearbuilder;

import com.banktaggearbuilder.model.BuildResult;
import com.banktaggearbuilder.model.EquipmentSlot;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.util.Text;

/**
 * Writes tags into the Bank Tags plugin's storage. Must be called on the client thread.
 * <p>
 * Tab names and icons are written to the Bank Tags config keys, which is what its TabManager
 * does on save. TabManager itself only holds the tab list while the bank is open, so it is
 * only updated (and only then saved through) when the bank is open and its list matches
 * the saved one. Saving through it with the bank closed would drop the player's other tabs.
 */
@Slf4j
@Singleton
public class BankTagWriter
{
	private final Client client;
	private final TagManager tagManager;
	private final TabManager tabManager;
	private final LayoutManager layoutManager;
	private final BankTagsService bankTagsService;
	private final ConfigManager configManager;

	@Inject
	private BankTagWriter(Client client, TagManager tagManager, TabManager tabManager, LayoutManager layoutManager,
		BankTagsService bankTagsService, ConfigManager configManager)
	{
		this.client = client;
		this.tagManager = tagManager;
		this.tabManager = tabManager;
		this.layoutManager = layoutManager;
		this.bankTagsService = bankTagsService;
		this.configManager = configManager;
	}

	public boolean isBankOpen()
	{
		return client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER) != null;
	}

	private List<String> savedTabNames()
	{
		return new ArrayList<>(Text.fromCSV(nullToEmpty(configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG))));
	}

	/**
	 * True when Bank Tags' in-memory tab list is loaded and agrees with the saved list, which
	 * means it is safe to change the list through TabManager and let it save.
	 */
	private boolean liveTabsLoaded()
	{
		if (!isBankOpen())
		{
			return false;
		}
		List<String> live = tabManager.getTabs().stream().map(TagTab::getTag).collect(Collectors.toList());
		return live.equals(savedTabNames());
	}

	/**
	 * Makes a name safe to use as a bank tag: lower case, no CSV or menu-breaking characters.
	 */
	public static String sanitizeTagName(String name)
	{
		String s = Text.standardize(name).replaceAll("[<>/:,*\"]", "").trim();
		return s.isEmpty() ? "gear" : s;
	}

	/**
	 * Creates or rewrites a tag so it contains exactly {@code itemIds}.
	 *
	 * @param exactIds        items tagged by exact id; every other item matches all its variants
	 * @param previousItemIds items this plugin previously wrote, removed if no longer wanted
	 */
	public void writeTag(String tag, List<Integer> itemIds, Set<Integer> exactIds, int iconItemId, List<Integer> previousItemIds, boolean layoutBySlot, BuildResult layoutSource)
	{
		tag = sanitizeTagName(tag);

		Set<Integer> wanted = new HashSet<>(itemIds);
		if (previousItemIds != null)
		{
			for (int old : previousItemIds)
			{
				if (!wanted.contains(old))
				{
					tagManager.removeTag(old, tag);
				}
			}
		}
		for (int id : itemIds)
		{
			boolean variation = !exactIds.contains(id);
			// Drop any stale tag of the other kind so a potion never matches all doses
			if (previousItemIds != null && previousItemIds.contains(id))
			{
				tagManager.removeTag(id, tag);
			}
			tagManager.addTag(id, tag, variation);
		}

		if (layoutBySlot && layoutSource != null)
		{
			layoutManager.saveLayout(buildLayout(tag, layoutSource));
		}

		if (liveTabsLoaded())
		{
			// Bank is open: register the tab with Bank Tags' live list so it is kept if the
			// player reorders or adds tabs before closing the bank, then save through it.
			TagTab tab = tabManager.find(tag);
			if (tab == null)
			{
				tab = new TagTab();
				tab.setTag(tag);
				tab.setIconItemId(iconItemId > 0 ? iconItemId : 0);
				tabManager.add(tab);
			}
			else if (iconItemId > 0)
			{
				tab.setIconItemId(iconItemId);
			}
			tabManager.save();
		}
		else
		{
			List<String> tabs = savedTabNames();
			if (!tabs.contains(tag))
			{
				tabs.add(tag);
				configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabs));
			}
			if (iconItemId > 0)
			{
				configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + tag, String.valueOf(iconItemId));
			}
		}

		if (isBankOpen())
		{
			// Show the new tag's contents right away. The tab strip itself is redrawn by
			// Bank Tags the next time the bank is opened.
			bankTagsService.openBankTag(tag, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
		}
	}

	/**
	 * Lays the tag out in the 8-wide bank grid, aiming for at most 9 rows and never more
	 * than needed. Equipment blocks (3 wide, 5 tall, shaped like the worn screen) sit side by
	 * side two per band, with two-handed, special attack and extra picks in the two columns
	 * to their right. The inventory fills a 4-wide area and the rune pouch sits beside it with
	 * its runes beneath it. With three styles the inventory and pouch go next to the third
	 * block instead of below it. Anything that does not fit spills into rows below.
	 * <pre>
	 *   .  H  .  .  H  .  2h S1      one or two styles: inventory below
	 *   C  N  A  C  N  A  S2 S3
	 *   W  B  Sh W  B  Sh .  .
	 *   .  L  .  .  L  .  .  .
	 *   G  F  R  G  F  R  .  .
	 *   I  I  I  I  .  P  .  .
	 *   I  I  I  I  .  R  R  .
	 * </pre>
	 */
	private static Layout buildLayout(String tag, BuildResult result)
	{
		final int w = BankTagsPlugin.BANK_ITEMS_PER_ROW;
		Grid grid = new Grid(tag, w);

		List<String> groups = result.getGroups();
		if (groups.isEmpty())
		{
			groups = new ArrayList<>();
			groups.add("");
		}
		int blocks = groups.size();
		int bands = (blocks + 1) / 2;

		// Reserve every block rectangle first so nothing else is packed into a block's gaps
		for (int g = 0; g < blocks; g++)
		{
			grid.reserveRect(blockRow(g), blockCol(g), 5, 3);
		}

		// Worn items into their block, everything else for the style into the band's spare columns
		List<BuildResult.SlotPick> deferred = new ArrayList<>();
		for (int g = 0; g < blocks; g++)
		{
			int row = blockRow(g);
			int col = blockCol(g);
			Set<EquipmentSlot> filled = new HashSet<>();
			List<Integer> spare = grid.rect(row, 6, 5, 2);
			for (BuildResult.SlotPick pick : result.getPicks())
			{
				if (!pick.getGroup().equals(groups.get(g)) || grid.has(pick.getItemId()))
				{
					continue;
				}
				int cell = filled.add(pick.getSlot()) ? equipmentCell(pick.getSlot(), w) : -1;
				if (cell >= 0)
				{
					grid.put(pick.getItemId(), w * row + col + cell);
				}
				else if (!grid.putFirstFree(pick.getItemId(), spare))
				{
					deferred.add(pick);
				}
			}
		}

		// Inventory area and pouch strip depend on how many blocks there are
		List<Integer> inventoryCells;
		int pouchCell;
		List<Integer> runeCells;
		if (blocks == 3)
		{
			inventoryCells = grid.rect(5, 3, 5, 4);
			pouchCell = w * 5 + 7;
			runeCells = grid.rect(6, 7, 4, 1);
		}
		else
		{
			int top = 5 * bands;
			inventoryCells = grid.rect(top, 0, 7, 4);
			pouchCell = w * top + 5;
			runeCells = grid.rect(top + 1, 5, 6, 2);
		}

		List<BuildResult.InventoryPick> runes = result.getRunePouch();
		BuildResult.InventoryPick pouch = null;
		if (!runes.isEmpty())
		{
			for (BuildResult.InventoryPick pick : result.getInventory())
			{
				if (pick.getName().toLowerCase().contains("rune pouch"))
				{
					pouch = pick;
					break;
				}
			}
		}

		List<BuildResult.InventoryPick> overflow = new ArrayList<>();
		for (BuildResult.InventoryPick pick : result.getInventory())
		{
			if (pick == pouch || grid.has(pick.getItemId()))
			{
				continue;
			}
			if (!grid.putFirstFree(pick.getItemId(), inventoryCells))
			{
				overflow.add(pick);
			}
		}
		if (pouch != null && !grid.has(pouch.getItemId()))
		{
			if (!grid.put(pouch.getItemId(), pouchCell))
			{
				overflow.add(pouch);
			}
		}
		for (BuildResult.InventoryPick rune : runes)
		{
			if (!grid.has(rune.getItemId()) && !grid.putFirstFree(rune.getItemId(), runeCells))
			{
				overflow.add(rune);
			}
		}

		// Spill-over: deferred picks first, then inventory, into free cells below the used area
		List<Integer> spill = grid.rect(grid.lastRow() + 1, 0, 8, w);
		for (BuildResult.SlotPick pick : deferred)
		{
			grid.putFirstFree(pick.getItemId(), spill);
		}
		for (BuildResult.InventoryPick pick : overflow)
		{
			grid.putFirstFree(pick.getItemId(), spill);
		}
		return grid.toLayout();
	}

	/** Blocks go two per band: (0,0) (0,3) (5,0) (5,3) ... */
	private static int blockRow(int block)
	{
		return 5 * (block / 2);
	}

	private static int blockCol(int block)
	{
		return 3 * (block % 2);
	}

	/** Cell offset within a 3-wide block for a worn slot, or -1 for slots that go in the spare columns. */
	private static int equipmentCell(EquipmentSlot slot, int w)
	{
		switch (slot)
		{
			case HEAD:
				return w * 0 + 1;
			case CAPE:
				return w * 1 + 0;
			case NECK:
				return w * 1 + 1;
			case AMMO:
				return w * 1 + 2;
			case WEAPON:
				return w * 2 + 0;
			case BODY:
				return w * 2 + 1;
			case SHIELD:
				return w * 2 + 2;
			case LEGS:
				return w * 3 + 1;
			case HANDS:
				return w * 4 + 0;
			case FEET:
				return w * 4 + 1;
			case RING:
				return w * 4 + 2;
			default:
				return -1;
		}
	}

	/**
	 * A sparse bank grid being filled: tracks which cells are taken or reserved and which
	 * items are already placed. Note Layout.setItemAtPos takes (itemId, pos).
	 */
	private static class Grid
	{
		private final Layout layout;
		private final int width;
		private final Set<Integer> taken = new HashSet<>();
		private final Set<Integer> reserved = new HashSet<>();
		private final Set<Integer> items = new HashSet<>();
		private int lastRow = -1;

		Grid(String tag, int width)
		{
			this.layout = new Layout(tag);
			this.width = width;
		}

		/** Cells of a rectangle, row by row. */
		List<Integer> rect(int row, int col, int rows, int cols)
		{
			List<Integer> cells = new ArrayList<>(rows * cols);
			for (int r = row; r < row + rows; r++)
			{
				for (int c = col; c < col + cols && c < width; c++)
				{
					cells.add(width * r + c);
				}
			}
			return cells;
		}

		/** Keeps a rectangle free for one block's shape so packing never spills into its gaps. */
		void reserveRect(int row, int col, int rows, int cols)
		{
			reserved.addAll(rect(row, col, rows, cols));
		}

		boolean has(int itemId)
		{
			return items.contains(itemId);
		}

		/** Places an item in a specific cell, which may be reserved for it. */
		boolean put(int itemId, int pos)
		{
			if (taken.contains(pos))
			{
				return false;
			}
			layout.setItemAtPos(itemId, pos);
			taken.add(pos);
			items.add(itemId);
			lastRow = Math.max(lastRow, pos / width);
			return true;
		}

		/** Places an item in the first cell of {@code cells} that is neither taken nor reserved. */
		boolean putFirstFree(int itemId, List<Integer> cells)
		{
			for (int pos : cells)
			{
				if (!taken.contains(pos) && !reserved.contains(pos))
				{
					return put(itemId, pos);
				}
			}
			return false;
		}

		int lastRow()
		{
			return lastRow;
		}

		Layout toLayout()
		{
			return layout;
		}
	}

	/**
	 * Items currently in the tag, as the ids Bank Tags stores them under.
	 */
	public List<Integer> currentItems(String tag)
	{
		return tagManager.getItemsForTag(sanitizeTagName(tag));
	}

	public void deleteTag(String tag)
	{
		tag = sanitizeTagName(tag);
		if (isBankOpen() && tag.equals(bankTagsService.getActiveTag()))
		{
			bankTagsService.closeBankTag();
		}
		tagManager.removeTag(tag);
		if (liveTabsLoaded())
		{
			tabManager.remove(tag);
			tabManager.save();
		}
		else
		{
			List<String> tabs = savedTabNames();
			if (tabs.remove(tag))
			{
				configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabs));
			}
			configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + tag);
		}
		layoutManager.removeLayout(tag);
	}

	/**
	 * The text Bank Tags' "Import tag tab" accepts. Negative ids tell it to match all
	 * variants of an item (charged, degraded, ornamented...); exact ids stay positive.
	 */
	public static String exportString(String tag, int iconItemId, List<Integer> itemIds, Set<Integer> exactIds)
	{
		List<String> data = new ArrayList<>();
		data.add("banktags");
		data.add("1");
		data.add(sanitizeTagName(tag));
		data.add(String.valueOf(Math.max(iconItemId, 0)));
		for (int id : itemIds)
		{
			data.add(String.valueOf(exactIds.contains(id) ? id : -id));
		}
		return Text.toCSV(data);
	}

	private static String nullToEmpty(String s)
	{
		return s == null ? "" : s;
	}
}

package com.banktaggearbuilder;

import com.banktaggearbuilder.model.Alternative;
import com.banktaggearbuilder.model.BuildResult;
import com.banktaggearbuilder.model.EquipmentSlot;
import com.banktaggearbuilder.model.GearSetup;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Picks the best-ranked owned item for each slot of a setup. Must run on the client thread
 * because it reads item compositions and prices.
 */
@Singleton
public class GearMatcher
{
	/** Trailing charge or dose marker, e.g. "Prayer potion(3)", "Amulet of glory(6)", "Ring of wealth (5)". */
	private static final Pattern CHARGE_SUFFIX = Pattern.compile("\\s?\\((\\d+)\\)$");
	private static final int MAX_CHARGE = 12;
	/** Trailing degrade level, e.g. "Ahrim's hood 75". */
	private static final Pattern DEGRADE_SUFFIX = Pattern.compile(" (\\d{1,3})$");

	/** Combination runes and the two elemental runes that replace them when not owned. */
	private static final Map<String, String[]> COMBINATION_RUNES = new HashMap<>();

	static
	{
		COMBINATION_RUNES.put("mist rune", new String[]{"Air rune", "Water rune"});
		COMBINATION_RUNES.put("dust rune", new String[]{"Air rune", "Earth rune"});
		COMBINATION_RUNES.put("mud rune", new String[]{"Water rune", "Earth rune"});
		COMBINATION_RUNES.put("smoke rune", new String[]{"Air rune", "Fire rune"});
		COMBINATION_RUNES.put("steam rune", new String[]{"Water rune", "Fire rune"});
		COMBINATION_RUNES.put("lava rune", new String[]{"Earth rune", "Fire rune"});
	}

	/** A name resolved to the one item that should be tagged for it. */
	@Value
	private static class Resolved
	{
		String name;
		int itemId;
		boolean exact;
	}

	/** The numbered variants of an item family, highest charge first, plus the unnumbered base. */
	@Value
	private static class ChargeFamily
	{
		String base;
		int maxCharge;
		/** Names from highest charge to lowest, then the base name if it is an item. */
		List<String> namesBestFirst;
	}

	private final ItemManager itemManager;
	private final ItemNameIndex index;
	private final OwnedItems owned;

	@Inject
	private GearMatcher(ItemManager itemManager, ItemNameIndex index, OwnedItems owned)
	{
		this.itemManager = itemManager;
		this.index = index;
		this.owned = owned;
	}

	public BuildResult match(GearSetup setup, boolean includeInventoryAndEquipment, boolean includeInventoryItems)
	{
		BuildResult result = new BuildResult();

		if (setup.isCombined())
		{
			for (GearSetup component : setup.getComponents())
			{
				matchEquipment(component, component.getStyle(), includeInventoryAndEquipment, result);
			}
		}
		else
		{
			matchEquipment(setup, "", includeInventoryAndEquipment, result);
		}

		if (includeInventoryItems)
		{
			for (List<String> names : setup.getInventory())
			{
				if (isPotion(names.get(0)))
				{
					addPotion(names.get(0), result);
					continue;
				}
				Resolved r = firstOwned(names, includeInventoryAndEquipment, result);
				if (r != null)
				{
					if (setup.isInventoryFromTiers() && isEquipable(r.getItemId()))
					{
						// Gear in a tiered example loadout belongs to the ranked tables, which
						// already picked the player's best; only supplies are taken from here
						continue;
					}
					if (!containsItem(result, r.getItemId()))
					{
						result.getInventory().add(new BuildResult.InventoryPick(r.getName(), r.getItemId(), r.isExact()));
					}
				}
				else if (!setup.isInventoryFromTiers())
				{
					result.getUnownedInventory().add(names.get(0));
				}
			}

			for (List<String> names : setup.getRunePouch())
			{
				addRune(names.get(0), includeInventoryAndEquipment, result);
			}

			mergeCombinationRunes(result.getRunePouch(), includeInventoryAndEquipment);
			mergeCombinationRunes(result.getInventory(), includeInventoryAndEquipment);
		}

		return result;
	}

	/**
	 * Where a list holds both elemental runes of a combination rune the player owns (fire and
	 * water with steam runes in the bank), the combination rune replaces the pair.
	 */
	private void mergeCombinationRunes(List<BuildResult.InventoryPick> picks, boolean includeInvEquip)
	{
		for (Map.Entry<String, String[]> e : COMBINATION_RUNES.entrySet())
		{
			BuildResult.InventoryPick first = findByName(picks, e.getValue()[0]);
			BuildResult.InventoryPick second = findByName(picks, e.getValue()[1]);
			if (first == null || second == null)
			{
				continue;
			}
			List<Integer> ids = index.lookup(e.getKey());
			if (ids.isEmpty())
			{
				continue;
			}
			int combo = OwnedItems.canonical(itemManager, ids.get(0));
			if (!owned.owns(combo, includeInvEquip))
			{
				continue;
			}
			int at = picks.indexOf(first);
			picks.remove(first);
			picks.remove(second);
			picks.add(Math.min(at, picks.size()), new BuildResult.InventoryPick(itemManager.getItemComposition(combo).getName(), combo, false));
		}
	}

	private static BuildResult.InventoryPick findByName(List<BuildResult.InventoryPick> picks, String name)
	{
		for (BuildResult.InventoryPick pick : picks)
		{
			if (pick.getName().equalsIgnoreCase(name))
			{
				return pick;
			}
		}
		return null;
	}

	private void matchEquipment(GearSetup setup, String group, boolean includeInvEquip, BuildResult result)
	{
		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			List<List<Alternative>> ranks = setup.getSlots().get(slot);
			if (ranks == null || ranks.isEmpty())
			{
				continue;
			}
			matchSlot(group, slot, ranks, includeInvEquip, result);
		}
	}

	private boolean isEquipable(int itemId)
	{
		ItemStats stats = itemManager.getItemStats(itemId);
		return stats != null && stats.isEquipable();
	}

	/** True if an equipment pick or inventory pick already carries this item. */
	private static boolean containsItem(BuildResult result, int itemId)
	{
		for (BuildResult.SlotPick pick : result.getPicks())
		{
			if (pick.getItemId() == itemId)
			{
				return true;
			}
		}
		for (BuildResult.InventoryPick pick : result.getInventory())
		{
			if (pick.getItemId() == itemId)
			{
				return true;
			}
		}
		return false;
	}

	private void matchSlot(String group, EquipmentSlot slot, List<List<Alternative>> ranks, boolean includeInvEquip, BuildResult result)
	{
		int bestSuggestion = -1;
		String bestSuggestionName = null;
		long bestPrice = Long.MAX_VALUE;
		int fallback = -1;
		String fallbackName = null;

		// Special attack weapons serve different jobs (defence drain, burst damage, core
		// dumping), so every owned one across the ranks is included, not only the best rank
		boolean takeAllRanks = slot == EquipmentSlot.SPECIAL;
		boolean pickedAny = false;

		for (int r = 0; r < ranks.size(); r++)
		{
			for (Alternative alternative : ranks.get(r))
			{
				// Every owned item of the alternative is picked ("Twisted bow + Toxic blowpipe")
				List<Resolved> ownedItems = new ArrayList<>();
				for (List<String> names : alternative.getItems())
				{
					Resolved pick = firstOwned(names, includeInvEquip, result);
					if (pick != null)
					{
						ownedItems.add(pick);
					}
				}
				if (!ownedItems.isEmpty())
				{
					for (Resolved pick : ownedItems)
					{
						if (!containsPick(result, group, pick.getItemId()))
						{
							result.getPicks().add(new BuildResult.SlotPick(group, slot, r + 1, pick.getName(), pick.getItemId(), pick.isExact()));
						}
					}
					pickedAny = true;
					if (!takeAllRanks)
					{
						return;
					}
					break;
				}

				// Not owned: remember the cheapest option as the suggestion for this slot
				for (List<String> names : alternative.getItems())
				{
					for (String name : names)
					{
						for (int id : index.lookup(name))
						{
							int canon = OwnedItems.canonical(itemManager, id);
							if (fallback < 0)
							{
								fallback = canon;
								fallbackName = name;
							}
							long price = itemManager.getItemPrice(canon);
							if (price > 0 && price < bestPrice)
							{
								bestPrice = price;
								bestSuggestion = canon;
								bestSuggestionName = name;
							}
						}
					}
				}
			}
		}

		if (pickedAny)
		{
			return;
		}
		if (bestSuggestion < 0)
		{
			bestSuggestion = fallback;
			bestSuggestionName = fallbackName;
			bestPrice = 0;
		}
		result.getMissing().add(new BuildResult.MissingSlot(group, slot, bestSuggestionName, bestSuggestion, bestPrice));
	}

	/** True if this style already picked the item in some slot (a weapon listed again as a special). */
	private static boolean containsPick(BuildResult result, String group, int itemId)
	{
		for (BuildResult.SlotPick pick : result.getPicks())
		{
			if (pick.getGroup().equals(group) && pick.getItemId() == itemId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * @return the item to tag for the first owned candidate name, or null if none is owned
	 */
	private Resolved firstOwned(List<String> names, boolean includeInvEquip, BuildResult result)
	{
		boolean resolvedAny = false;
		for (String name : names)
		{
			List<Integer> ids = index.lookup(name);
			ChargeFamily family = chargeFamily(name);
			if (ids.isEmpty() && family == null)
			{
				continue;
			}
			resolvedAny = true;

			// Charged items: use only the highest charge the player actually has
			if (family != null)
			{
				for (String variant : family.getNamesBestFirst())
				{
					for (int id : index.lookup(variant))
					{
						int exact = itemManager.canonicalize(id);
						if (owned.ownsExact(exact, includeInvEquip))
						{
							return new Resolved(itemManager.getItemComposition(exact).getName(), exact, true);
						}
					}
				}
			}

			for (int id : ids)
			{
				int canon = OwnedItems.canonical(itemManager, id);
				if (owned.owns(canon, includeInvEquip))
				{
					Resolved best = bestOwnedVariant(canon, includeInvEquip);
					return best != null ? best : new Resolved(itemManager.getItemComposition(canon).getName(), canon, false);
				}
			}
		}
		if (!resolvedAny && !names.isEmpty())
		{
			result.getUnresolvedNames().add(names.get(0));
		}
		return null;
	}

	/**
	 * When the player owns several variants of one item ("Dizana's quiver (uncharged)" and
	 * "Dizana's quiver", "Masori body" and "Masori body (f)"), tagging by variation would show
	 * all of them, so only the best owned variant is tagged, by exact id.
	 *
	 * @return the best owned variant, or null if fewer than two variants are owned
	 */
	private Resolved bestOwnedVariant(int canonicalId, boolean includeInvEquip)
	{
		int best = -1;
		String bestName = null;
		int bestScore = Integer.MIN_VALUE;
		int ownedCount = 0;
		for (int id : ItemVariationMapping.getVariations(canonicalId))
		{
			if (!owned.ownsExact(id, includeInvEquip))
			{
				continue;
			}
			ownedCount++;
			String name = itemManager.getItemComposition(id).getName();
			int score = variantScore(name);
			if (score > bestScore || (score == bestScore && id < best))
			{
				best = id;
				bestName = name;
				bestScore = score;
			}
		}
		return ownedCount < 2 ? null : new Resolved(bestName, best, true);
	}

	/**
	 * Higher is better: uncharged or broken copies lose, fortified "(f)" upgrades win, and
	 * degraded items ("Ahrim's hood 75") prefer the most charge left. Locked "(l)" copies
	 * count the same as the plain item.
	 */
	private static int variantScore(String name)
	{
		String lower = name.toLowerCase(Locale.ROOT);
		int score = 0;
		if (lower.contains("uncharged") || lower.contains("broken") || lower.contains("inactive") || lower.contains("(empty)"))
		{
			score -= 1000;
		}
		if (lower.endsWith("(f)"))
		{
			score += 500;
		}
		Matcher m = DEGRADE_SUFFIX.matcher(lower);
		if (m.find())
		{
			score += Integer.parseInt(m.group(1));
		}
		return score;
	}

	/**
	 * Finds the numbered variants of a name such as "Amulet of glory" or "Ring of dueling(8)".
	 * Returns null when the item has no "(N)" variants in the game cache.
	 */
	private ChargeFamily chargeFamily(String name)
	{
		String base = CHARGE_SUFFIX.matcher(name).replaceFirst("");
		List<String> found = new ArrayList<>();
		int max = 0;
		for (int charge = MAX_CHARGE; charge >= 1; charge--)
		{
			String tight = base + "(" + charge + ")";
			String spaced = base + " (" + charge + ")";
			if (!index.lookup(tight).isEmpty())
			{
				found.add(tight);
			}
			else if (!index.lookup(spaced).isEmpty())
			{
				found.add(spaced);
			}
			else
			{
				continue;
			}
			max = Math.max(max, charge);
		}
		if (found.isEmpty())
		{
			return null;
		}
		if (!index.lookup(base).isEmpty())
		{
			found.add(base);
		}
		return new ChargeFamily(base, max, found);
	}

	/**
	 * Potions have doses 1-4 and are not equipable; anything numbered beyond 4 or wearable
	 * (jewellery, charged weapons) is a charged item instead.
	 */
	private boolean isPotion(String name)
	{
		Matcher m = CHARGE_SUFFIX.matcher(name);
		if (!m.find())
		{
			return false;
		}
		ChargeFamily family = chargeFamily(name);
		if (family == null || family.getMaxCharge() > 4)
		{
			return false;
		}
		for (int id : index.lookup(family.getNamesBestFirst().get(0)))
		{
			ItemStats stats = itemManager.getItemStats(id);
			if (stats != null && stats.isEquipable())
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Potions are always tagged as exactly their 4-dose item, owned or not, so the tag never
	 * shows partly used doses.
	 */
	private void addPotion(String name, BuildResult result)
	{
		String fourDose = CHARGE_SUFFIX.matcher(name).replaceFirst("(4)");
		List<Integer> ids = index.lookup(fourDose);
		if (ids.isEmpty())
		{
			result.getUnresolvedNames().add(fourDose);
			return;
		}
		// Lowest id is the ordinary item; higher duplicates are minigame or quest copies
		int id = itemManager.canonicalize(ids.get(0));
		if (!containsItem(result, id))
		{
			result.getInventory().add(new BuildResult.InventoryPick(fourDose, id, true));
		}
	}

	/**
	 * Runes are consumables, so they are always included. A combination rune the player does
	 * not own is replaced by its two elemental runes, which the wiki lists as the alternative.
	 */
	private void addRune(String name, boolean includeInvEquip, BuildResult result)
	{
		List<Integer> ids = index.lookup(name);
		if (ids.isEmpty())
		{
			result.getUnresolvedNames().add(name);
			return;
		}
		int id = OwnedItems.canonical(itemManager, ids.get(0));
		String[] components = COMBINATION_RUNES.get(name.toLowerCase(Locale.ROOT));
		if (components != null && !owned.owns(id, includeInvEquip))
		{
			for (String component : components)
			{
				addRune(component, includeInvEquip, result);
			}
			return;
		}
		for (BuildResult.InventoryPick existing : result.getRunePouch())
		{
			if (existing.getItemId() == id)
			{
				return;
			}
		}
		result.getRunePouch().add(new BuildResult.InventoryPick(itemManager.getItemComposition(id).getName(), id, false));
	}

	/**
	 * Fills {@code into} with "[style] slot" to item name, used for before/after diffs.
	 */
	public static void summarize(BuildResult result, Map<String, String> into)
	{
		into.clear();
		for (BuildResult.SlotPick pick : result.getPicks())
		{
			String key = (pick.getGroup().isEmpty() ? "" : pick.getGroup() + " ") + pick.getSlot().getDisplayName();
			// Several picks in one slot ("Twisted bow + Toxic blowpipe") are joined
			into.merge(key, pick.getName(), (a, b) -> a + " + " + b);
		}
	}
}

package com.banktaggearbuilder;

import com.banktaggearbuilder.model.GeneratedTag;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Persists the tags this plugin generated in the plugin's config group, one JSON entry per tag.
 */
@Slf4j
@Singleton
public class GeneratedTagStore
{
	static final String KEY_PREFIX = "tag_";

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	private GeneratedTagStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public List<GeneratedTag> loadAll()
	{
		List<GeneratedTag> tags = new ArrayList<>();
		String prefix = BankTagGearBuilderConfig.GROUP + "." + KEY_PREFIX;
		for (String fullKey : configManager.getConfigurationKeys(prefix))
		{
			String key = fullKey.substring(BankTagGearBuilderConfig.GROUP.length() + 1);
			String json = configManager.getConfiguration(BankTagGearBuilderConfig.GROUP, key);
			if (json == null)
			{
				continue;
			}
			try
			{
				GeneratedTag tag = gson.fromJson(json, GeneratedTag.class);
				if (tag != null && tag.getTag() != null && tag.getSetup() != null)
				{
					tags.add(tag);
				}
			}
			catch (Exception e)
			{
				log.debug("Dropping unreadable generated tag {}", key, e);
				configManager.unsetConfiguration(BankTagGearBuilderConfig.GROUP, key);
			}
		}
		tags.sort((a, b) -> a.getTag().compareToIgnoreCase(b.getTag()));
		return tags;
	}

	public void save(GeneratedTag tag)
	{
		configManager.setConfiguration(BankTagGearBuilderConfig.GROUP, KEY_PREFIX + tag.getTag(), gson.toJson(tag));
	}

	public void remove(String tag)
	{
		configManager.unsetConfiguration(BankTagGearBuilderConfig.GROUP, KEY_PREFIX + tag);
	}
}

package com.banktaggearbuilder;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/**
 * Maps in-game item names to item ids. Built once per session on the client thread, a
 * chunk per frame so the client does not stall. Notes and placeholders are skipped.
 */
@Slf4j
@Singleton
public class ItemNameIndex
{
	private static final int CHUNK = 2500;

	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;

	private final Map<String, List<Integer>> byName = new HashMap<>();
	private volatile boolean ready;
	private boolean building;
	private int nextId;

	@Inject
	private ItemNameIndex(Client client, ClientThread clientThread, ItemManager itemManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
	}

	public boolean isReady()
	{
		return ready;
	}

	/**
	 * Starts building if not already built or building. Safe to call from any thread.
	 * {@code onReady} runs on the client thread once the index is complete.
	 */
	public void ensureBuilt(Runnable onReady)
	{
		clientThread.invoke(() ->
		{
			if (ready)
			{
				onReady.run();
				return;
			}
			if (building)
			{
				return;
			}
			building = true;
			nextId = 0;
			clientThread.invoke(() -> step(onReady));
		});
	}

	private boolean step(Runnable onReady)
	{
		int count = client.getItemCount();
		int end = Math.min(count, nextId + CHUNK);
		for (int id = nextId; id < end; id++)
		{
			ItemComposition c = itemManager.getItemComposition(id);
			String name = c.getName();
			if (name == null || name.equalsIgnoreCase("null") || c.getNote() != -1 || c.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			byName.computeIfAbsent(name.toLowerCase(Locale.ROOT), k -> new ArrayList<>()).add(id);
		}
		nextId = end;
		if (nextId >= count)
		{
			ready = true;
			building = false;
			log.debug("Item name index built: {} names", byName.size());
			onReady.run();
			return true;
		}
		return false;
	}

	/**
	 * Returns every item id with exactly this name (case-insensitive), or an empty list.
	 */
	public List<Integer> lookup(String name)
	{
		List<Integer> ids = byName.get(name.toLowerCase(Locale.ROOT));
		return ids == null ? Collections.emptyList() : ids;
	}
}

package com.banktaggearbuilder;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Tracks what the player owns in the bank, inventory and equipment, keyed by the
 * canonical (un-noted, base variation) item id. Updated on the client thread.
 */
@Singleton
public class OwnedItems
{
	private final ItemManager itemManager;

	/** Exact (un-noted) item id -> quantity, per container. */
	private final Map<Integer, Integer> bank = new HashMap<>();
	private final Map<Integer, Integer> inventory = new HashMap<>();
	private final Map<Integer, Integer> equipment = new HashMap<>();
	/** Base-variation id -> quantity, derived from the maps above. */
	private final Map<Integer, Integer> bankVariants = new HashMap<>();
	private final Map<Integer, Integer> inventoryVariants = new HashMap<>();
	private final Map<Integer, Integer> equipmentVariants = new HashMap<>();

	/** True once the bank contents are known, from the live bank or a saved cache. */
	@Getter
	private volatile boolean bankSeen;

	/** True while the bank contents come from a saved cache rather than this session's bank. */
	@Getter
	private volatile boolean bankFromCache;

	/** When the cached bank was saved, epoch millis, or 0. */
	@Getter
	private volatile long cacheSavedAt;

	@Inject
	private OwnedItems(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * Un-notes and un-placeholders an item, then maps it to its base variation so that
	 * charged, degraded, imbued and ornamented versions all compare equal.
	 */
	public static int canonical(ItemManager itemManager, int itemId)
	{
		return ItemVariationMapping.map(itemManager.canonicalize(itemId));
	}

	/**
	 * @return true if the container is one we track
	 */
	public boolean update(int containerId, ItemContainer container)
	{
		Map<Integer, Integer> target;
		Map<Integer, Integer> variants;
		switch (containerId)
		{
			case InventoryID.BANK:
				target = bank;
				variants = bankVariants;
				bankSeen = true;
				bankFromCache = false;
				break;
			case InventoryID.INV:
				target = inventory;
				variants = inventoryVariants;
				break;
			case InventoryID.WORN:
				target = equipment;
				variants = equipmentVariants;
				break;
			default:
				return false;
		}

		target.clear();
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				// Bank placeholders stand in for items the player no longer has
				if (itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() != -1)
				{
					continue;
				}
				target.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		rebuildVariants(target, variants);
		return true;
	}

	private static void rebuildVariants(Map<Integer, Integer> exact, Map<Integer, Integer> variants)
	{
		variants.clear();
		for (Map.Entry<Integer, Integer> e : exact.entrySet())
		{
			variants.merge(ItemVariationMapping.map(e.getKey()), e.getValue(), Integer::sum);
		}
	}

	public void clear()
	{
		bank.clear();
		inventory.clear();
		equipment.clear();
		bankVariants.clear();
		inventoryVariants.clear();
		equipmentVariants.clear();
		bankSeen = false;
		bankFromCache = false;
		cacheSavedAt = 0;
	}

	/**
	 * Whether this exact item id (a specific charge or dose) is owned.
	 */
	public boolean ownsExact(int exactId, boolean includeInventoryAndEquipment)
	{
		if (bank.containsKey(exactId))
		{
			return true;
		}
		return includeInventoryAndEquipment && (inventory.containsKey(exactId) || equipment.containsKey(exactId));
	}

	/**
	 * Compact form of the bank for saving: {@code savedAt;id=qty,id=qty,...}
	 */
	public String serializeBank()
	{
		StringBuilder sb = new StringBuilder(bank.size() * 10 + 16);
		sb.append(System.currentTimeMillis()).append(';');
		boolean first = true;
		for (Map.Entry<Integer, Integer> e : bank.entrySet())
		{
			if (!first)
			{
				sb.append(',');
			}
			first = false;
			sb.append(e.getKey()).append('=').append(e.getValue());
		}
		return sb.toString();
	}

	/**
	 * Restores a bank saved by {@link #serializeBank()}. Does nothing if the live bank has
	 * already been seen this session.
	 *
	 * @return true if the cache was applied
	 */
	public boolean loadBank(String serialized)
	{
		if (bankSeen && !bankFromCache)
		{
			return false;
		}
		if (serialized == null || serialized.isEmpty())
		{
			return false;
		}
		int sep = serialized.indexOf(';');
		if (sep < 0)
		{
			return false;
		}
		Map<Integer, Integer> loaded = new HashMap<>();
		try
		{
			long savedAt = Long.parseLong(serialized.substring(0, sep));
			String body = serialized.substring(sep + 1);
			if (!body.isEmpty())
			{
				for (String entry : body.split(","))
				{
					int eq = entry.indexOf('=');
					loaded.put(Integer.parseInt(entry.substring(0, eq)), Integer.parseInt(entry.substring(eq + 1)));
				}
			}
			bank.clear();
			bank.putAll(loaded);
			rebuildVariants(bank, bankVariants);
			cacheSavedAt = savedAt;
		}
		catch (RuntimeException e)
		{
			return false;
		}
		bankSeen = true;
		bankFromCache = true;
		return true;
	}

	/**
	 * Whether any variant of this base-variation id is owned.
	 */
	public boolean owns(int canonicalId, boolean includeInventoryAndEquipment)
	{
		if (bankVariants.containsKey(canonicalId))
		{
			return true;
		}
		return includeInventoryAndEquipment && (inventoryVariants.containsKey(canonicalId) || equipmentVariants.containsKey(canonicalId));
	}
}

package com.banktaggearbuilder.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Data;

/**
 * One choice within a rank of a slot. Usually a single item, but the wiki sometimes joins
 * items that go together with "+" or "and" (e.g. "Twisted bow + Toxic blowpipe"), in which
 * case every owned item of the group is picked.
 * <p>
 * Each item is a list of candidate names: the wiki page name first, then the "pic=" item name.
 */
@Data
public class Alternative
{
	private List<List<String>> items = new ArrayList<>();

	public static Alternative single(List<String> names)
	{
		Alternative a = new Alternative();
		a.items.add(names);
		return a;
	}

	public static Alternative single(String name)
	{
		return single(Collections.singletonList(name));
	}
}

package com.banktaggearbuilder.model;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import lombok.Data;
import lombok.Value;

/**
 * The outcome of matching a {@link GearSetup} against what the player owns.
 */
@Data
public class BuildResult
{
	@Value
	public static class SlotPick
	{
		/** Style of the component setup this pick belongs to; empty for a single setup. */
		String group;
		EquipmentSlot slot;
		int rank;
		String name;
		/** The item id to tag. Unless exactVariant is set, every variant of this item matches. */
		int itemId;
		/** Tag exactly this id (used for charged items such as Amulet of glory(6)). */
		boolean exactVariant;
	}

	@Value
	public static class MissingSlot
	{
		String group;
		EquipmentSlot slot;
		/** Cheapest recommended item, or null if no name on the list could be resolved. */
		String suggestionName;
		int suggestionItemId;
		long suggestionPrice;
	}

	/** Group names in the order they first appear among picks and missing slots. */
	public List<String> getGroups()
	{
		Set<String> groups = new LinkedHashSet<>();
		for (SlotPick pick : picks)
		{
			groups.add(pick.getGroup());
		}
		for (MissingSlot miss : missing)
		{
			groups.add(miss.getGroup());
		}
		return new ArrayList<>(groups);
	}

	@Value
	public static class InventoryPick
	{
		String name;
		int itemId;
		/** Tag exactly this item id rather than all of its variants (used for 4-dose potions). */
		boolean exactVariant;
	}

	private final List<SlotPick> picks = new ArrayList<>();
	private final List<MissingSlot> missing = new ArrayList<>();
	private final List<InventoryPick> inventory = new ArrayList<>();
	/** Runes for the rune pouch, kept apart from the inventory items. */
	private final List<InventoryPick> runePouch = new ArrayList<>();
	private final List<String> unownedInventory = new ArrayList<>();
	private final Set<String> unresolvedNames = new LinkedHashSet<>();

	/**
	 * Item ids to include in the tag, in equipment-slot order followed by inventory order.
	 */
	public List<Integer> getTagItemIds()
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (SlotPick pick : picks)
		{
			ids.add(pick.getItemId());
		}
		for (InventoryPick pick : inventory)
		{
			ids.add(pick.getItemId());
		}
		for (InventoryPick pick : runePouch)
		{
			ids.add(pick.getItemId());
		}
		return new ArrayList<>(ids);
	}

	/** Item ids that must be tagged exactly, without variant matching. */
	public Set<Integer> getExactItemIds()
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (SlotPick pick : picks)
		{
			if (pick.isExactVariant())
			{
				ids.add(pick.getItemId());
			}
		}
		for (InventoryPick pick : inventory)
		{
			if (pick.isExactVariant())
			{
				ids.add(pick.getItemId());
			}
		}
		return ids;
	}

	/** The item used as the tag tab icon: the best weapon, else the first picked item. */
	public int getIconItemId()
	{
		for (SlotPick pick : picks)
		{
			if (pick.getSlot() == EquipmentSlot.WEAPON || pick.getSlot() == EquipmentSlot.TWO_HANDED)
			{
				return pick.getItemId();
			}
		}
		if (!picks.isEmpty())
		{
			return picks.get(0).getItemId();
		}
		if (!inventory.isEmpty())
		{
			return inventory.get(0).getItemId();
		}
		return -1;
	}
}

package com.banktaggearbuilder.model;

import lombok.Value;

/**
 * A wiki page that contains at least one Recommended equipment table.
 */
@Value
public class ContentPage
{
	String title;
	/** Name shown in the picker; null means derive it from the title. */
	String displayOverride;

	public ContentPage(String title)
	{
		this(title, null);
	}

	public ContentPage(String title, String displayOverride)
	{
		this.title = title;
		this.displayOverride = displayOverride;
	}

	/** The short name derived from the title: "Vorkath/Strategies" becomes "Vorkath". */
	public static String shortName(String title)
	{
		String name = title;
		if (name.endsWith("/Strategies"))
		{
			name = name.substring(0, name.length() - "/Strategies".length());
		}
		int slash = name.indexOf('/');
		if (slash > 0)
		{
			// e.g. "Slayer task/Dark beast" -> "Dark beast (Slayer task)"
			name = name.substring(slash + 1) + " (" + name.substring(0, slash) + ")";
		}
		return name;
	}

	public String getDisplayName()
	{
		return displayOverride != null ? displayOverride : shortName(title);
	}

	@Override
	public String toString()
	{
		return getDisplayName();
	}
}

package com.banktaggearbuilder.model;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Equipment slots in the order the wiki's Recommended equipment template uses them,
 * which is also the order items are laid out in generated tags.
 */
@Getter
@RequiredArgsConstructor
public enum EquipmentSlot
{
	HEAD("head", "Head"),
	CAPE("cape", "Cape"),
	NECK("neck", "Neck"),
	AMMO("ammo", "Ammo"),
	WEAPON("weapon", "Weapon"),
	TWO_HANDED("2h", "Two-handed"),
	SHIELD("shield", "Shield"),
	BODY("body", "Body"),
	LEGS("legs", "Legs"),
	HANDS("hands", "Hands"),
	FEET("feet", "Feet"),
	RING("ring", "Ring"),
	SPECIAL("special", "Special attack");

	private final String wikiParam;
	private final String displayName;

	public static EquipmentSlot fromWikiParam(String param)
	{
		for (EquipmentSlot slot : values())
		{
			if (slot.wikiParam.equals(param))
			{
				return slot;
			}
		}
		return null;
	}
}

package com.banktaggearbuilder.model;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import lombok.Data;

/**
 * One "Recommended equipment" table from a wiki strategy page, plus the inventory and rune
 * pouch that go with it if the page lists them.
 * <p>
 * Each slot holds ranked entries (rank 1 is best). Each rank may list several alternatives
 * (the wiki separates them with "/"), and an alternative may group items that go together.
 * <p>
 * A combined setup has {@link #components}: several tables (e.g. melee, ranged and magic
 * switches for a raid) that are all built into one tag.
 */
@Data
public class GearSetup
{
	private String style = "";
	/** The wiki section heading the table sits under, for telling similar tables apart. */
	private String section = "";
	private Map<EquipmentSlot, List<List<Alternative>>> slots = new EnumMap<>(EquipmentSlot.class);
	/** Inventory entries in slot order (1-28). Each entry is a list of alternative names. */
	private List<List<String>> inventory = new ArrayList<>();
	/** Runes the wiki puts in the rune pouch for this setup, if it lists a pouch. */
	private List<List<String>> runePouch = new ArrayList<>();
	/**
	 * True when the inventory is the union of several example loadouts of different tiers
	 * rather than one list for this style. Only supplies are taken from such an inventory,
	 * since its gear belongs to the ranked tables.
	 */
	private boolean inventoryFromTiers;
	/** For a combined setup, the tables it is made of; empty otherwise. */
	private List<GearSetup> components = new ArrayList<>();

	public void addRank(EquipmentSlot slot, int rank, List<Alternative> alternatives)
	{
		List<List<Alternative>> ranks = slots.computeIfAbsent(slot, s -> new ArrayList<>());
		while (ranks.size() < rank)
		{
			ranks.add(new ArrayList<>());
		}
		ranks.set(rank - 1, alternatives);
	}

	public boolean isCombined()
	{
		return components != null && !components.isEmpty();
	}

	public boolean isEmpty()
	{
		return !isCombined() && slots.values().stream().allMatch(r -> r.stream().allMatch(List::isEmpty));
	}

	/** Text for the setup picker: "Section: style", or just the style. */
	public String getDisplayName()
	{
		String s = style == null || style.isEmpty() ? "Default setup" : style;
		return section == null || section.isEmpty() ? s : section + ": " + s;
	}
}

