	/**
	 * BoxLayout positions each child by its own alignment hint, and buttons, combo boxes and
	 * panels default to centred, which reads as right-aligned next to left-aligned labels.
	 * Pin every child to the left edge and let it use the full panel width.
	 */
	private static void leftAlign(JPanel vertical)
	{
		for (Component c : vertical.getComponents())
		{
			if (c instanceof JComponent)
			{
				JComponent jc = (JComponent) c;
				jc.setAlignmentX(Component.LEFT_ALIGNMENT);
				jc.setMaximumSize(new Dimension(Integer.MAX_VALUE, jc.getMaximumSize().height));
			}
		}
	}

	@Override
	public void onActivate()
	{
		updateStatusLabel();
		if (allContent.isEmpty())
		{
			loadContentList(false);
		}
	}

	/**
	 * Fills the content list.
	 *
	 * @param force skip the saved list and download it from the wiki
	 */
	private void loadContentList(boolean force)
	{
		if (contentLoading)
		{
			return;
		}
		contentLoading = true;
		setWrapped(statusLabel, "Loading content list from the OSRS Wiki...");
		plugin.loadContent(force, pages ->
		{
			contentLoading = false;
			allContent = pages;
			filterContent();
			updateStatusLabel();
		}, err ->
		{
			contentLoading = false;
			setWrapped(statusLabel, err);
		});
	}

	public void onConfigChanged()
	{
		switch (config.outputMode())
		{
			case CREATE_TAG:
				buildButton.setText("Build and create tag");
				break;
			case COPY_IMPORT_STRING:
				buildButton.setText("Build and copy import string");
				break;
			default:
				buildButton.setText("Build setup");
				break;
		}
	}

	private void updateStatusLabel()
	{
		if (!plugin.isLoggedIn())
		{
			showBanner("LOG IN FIRST. Gear is matched against your bank, so the plugin needs you logged in.");
		}
		else if (!plugin.isBankSeen())
		{
			showBanner("OPEN YOUR BANK ONCE. The plugin only knows what you own after it has seen your bank this session. Builds and update checks wait until then.");
		}
		else
		{
			banner.setVisible(false);
			body.setVisible(true);
			if (plugin.isBankFromCache())
			{
				setWrapped(statusLabel, "Source: OSRS Wiki. Using your bank as saved on " + formatDate(plugin.getBankCacheSavedAt()) + ". Open the bank to refresh it.");
			}
			else
			{
				setWrapped(statusLabel, "Source: OSRS Wiki. Bank seen this session.");
			}
		}
		revalidate();
		repaint();
	}

	private void showBanner(String text)
	{
		setWrapped(bannerLabel, text);
		banner.setVisible(true);
		body.setVisible(false);
		setWrapped(statusLabel, "");
	}

	private void filterContent()
	{
		String q = searchField.getText() == null ? "" : searchField.getText().trim().toLowerCase(Locale.ROOT);
		ContentPage selected = contentList.getSelectedValue();
		listModel.clear();
		for (ContentPage page : allContent)
		{
			if (q.isEmpty() || page.getDisplayName().toLowerCase(Locale.ROOT).contains(q))
			{
				listModel.addElement(page);
			}
		}
		if (selected != null && listModel.contains(selected))
		{
			contentList.setSelectedValue(selected, false);
		}
	}

	private void selectContent(ContentPage page)
	{
		if (page.equals(selectedContent))
		{
			// Re-selected after the list was filtered; nothing to fetch
			return;
		}
		selectedContent = page;
		syncButton.setVisible(true);
		loadPage(page, false);
	}

	private void confirmSync()
	{
		ContentPage page = selectedContent;
		if (page == null)
		{
			return;
		}
		int choice = JOptionPane.showConfirmDialog(this,
			"Download " + page.getDisplayName() + " and the content list from the OSRS Wiki again?" + System.lineSeparator()
				+ "The saved copies are replaced with the current wiki versions.",
			"Sync from wiki", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE);
		if (choice == JOptionPane.YES_OPTION)
		{
			loadPage(page, true);
			loadContentList(true);
		}
	}

	/**
	 * Fetches a page's setups and fills the setup picker.
	 *
	 * @param force skip the saved copy and download the page from the wiki
	 */
	private void loadPage(ContentPage page, boolean force)
	{
		currentPage = null;
		clearResult();
		setupCombo.setModel(new DefaultComboBoxModel<>());
		setupCombo.setEnabled(false);
		buildButton.setEnabled(false);
		syncButton.setEnabled(false);
		setWrapped(sourceLabel, (force ? "Syncing " : "Fetching ") + page.getDisplayName() + "...");

		plugin.fetchStrategy(page, force, sp ->
		{
			if (contentList.getSelectedValue() == null || !contentList.getSelectedValue().equals(page))
			{
				return;
			}
			currentPage = sp;
			DefaultComboBoxModel<GearSetup> model = new DefaultComboBoxModel<>();
			for (GearSetup s : sp.getSetups())
			{
				model.addElement(s);
			}
			setupCombo.setModel(model);
			setupCombo.setEnabled(true);
			buildButton.setEnabled(true);
			syncButton.setEnabled(true);
			setWrapped(sourceLabel, "Source: OSRS Wiki, pulled " + formatDate(sp.getFetchedAt()) + ". " + sp.getSetups().size() + " setup(s).");
		}, err ->
		{
			if (page.equals(selectedContent))
			{
				syncButton.setEnabled(true);
				setWrapped(sourceLabel, err);
			}
		});
	}

	private GearSetup selectedSetup()
	{
		Object s = setupCombo.getSelectedItem();
		return s instanceof GearSetup ? (GearSetup) s : null;
	}

	private void clearResult()
	{
		currentResult = null;
		resultSetup = null;
		actionRow.setVisible(false);
		resultPanel.removeAll();
		resultPanel.revalidate();
		resultPanel.repaint();
	}

	/** True if the shown result was built for the setup currently selected. */
	private boolean resultMatchesSelection()
	{
		GearSetup setup = selectedSetup();
		if (currentResult == null || resultSetup == null || setup != resultSetup)
		{
			clearResult();
			setWrapped(statusLabel, "Press Build for this setup first.");
			return false;
		}
		return true;
	}

	private void build()
	{
		GearSetup setup = selectedSetup();
		if (currentPage == null || setup == null)
		{
			return;
		}
		if (!plugin.isLoggedIn() || !plugin.isBankSeen())
		{
			// The banner already says what to do; make sure it is showing
			updateStatusLabel();
			return;
		}
		buildButton.setEnabled(false);
		setWrapped(statusLabel, "Matching against your bank...");
		plugin.build(currentPage.getPage(), setup, result ->
		{
			buildButton.setEnabled(true);
			if (selectedSetup() != setup)
			{
				// Selection changed while matching; this result is for a setup no longer chosen
				return;
			}
			currentResult = result;
			resultSetup = setup;
			createButton.setText(plugin.hasGeneratedTag(plugin.tagNameFor(currentPage.getPage(), setup)) ? "Update tag" : "Create tag");
			showResult(result);
			updateStatusLabel();
			switch (config.outputMode())
			{
				case CREATE_TAG:
					doCreate();
					break;
				case COPY_IMPORT_STRING:
					doCopy();
					break;
				default:
					break;
			}
		});
	}

	private void doCreate()
	{
		GearSetup setup = selectedSetup();
		if (currentPage == null || setup == null || !resultMatchesSelection())
		{
			return;
		}
		if (currentResult.getTagItemIds().isEmpty())
		{
			setWrapped(statusLabel, "Nothing to tag: you own none of the recommended items.");
			return;
		}
		String tag = plugin.tagNameFor(currentPage.getPage(), setup);
		for (TagStatus status : currentStatuses)
		{
			if (status.getTag().getTag().equals(tag) && status.isUserEdited())
			{
				int choice = JOptionPane.showConfirmDialog(this,
					"You edited the tag '" + tag + "' yourself in Bank Tags.\nUpdating it replaces your edits with this result. Continue?",
					"Overwrite your edits?", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
				if (choice != JOptionPane.YES_OPTION)
				{
					return;
				}
			}
		}
		createButton.setEnabled(false);
		plugin.createTag(currentPage, setup, currentResult, created ->
		{
			createButton.setEnabled(true);
			setWrapped(statusLabel, "Created tag tab '" + created + "'. If the bank is open it shows the tag now; the tab itself appears next time the bank opens.");
		});
	}

	private void doCopy()
	{
		GearSetup setup = selectedSetup();
		if (currentPage == null || setup == null || !resultMatchesSelection())
		{
			return;
		}
		String tag = plugin.tagNameFor(currentPage.getPage(), setup);
		copyToClipboard(BankTagWriter.exportString(tag, currentResult.getIconItemId(), currentResult.getTagItemIds(), currentResult.getExactItemIds()));
		setWrapped(statusLabel, "Import string copied. In the bank, right-click the tag tab '+' and choose Import tag tab.");
	}

	private void copyToClipboard(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
	}

	private void showResult(BuildResult result)
	{
		resultPanel.removeAll();

		List<String> groups = result.getGroups();
		for (String group : groups)
		{
			if (groups.size() > 1 || !group.isEmpty())
			{
				resultPanel.add(header(group.isEmpty() ? "Equipment" : group));
			}
			for (BuildResult.SlotPick pick : result.getPicks())
			{
				if (pick.getGroup().equals(group))
				{
					resultPanel.add(itemRow(pick.getItemId(), pick.getSlot().getDisplayName(), pick.getName() + "  (#" + pick.getRank() + ")", Color.WHITE));
				}
			}
			for (BuildResult.MissingSlot miss : result.getMissing())
			{
				if (!miss.getGroup().equals(group))
				{
					continue;
				}
				String detail = miss.getSuggestionName() == null
					? "none owned"
					: "none owned. Cheapest: " + miss.getSuggestionName()
					+ (miss.getSuggestionPrice() > 0 ? " (" + QuantityFormatter.quantityToStackSize(miss.getSuggestionPrice()) + " gp)" : "");
				resultPanel.add(itemRow(miss.getSuggestionItemId(), miss.getSlot().getDisplayName(), detail, MUTED));
			}
		}

		if (!result.getInventory().isEmpty())
		{
			resultPanel.add(Box.createVerticalStrut(4));
			resultPanel.add(header("Inventory"));
			for (BuildResult.InventoryPick pick : result.getInventory())
			{
				resultPanel.add(itemRow(pick.getItemId(), null, pick.getName(), Color.WHITE));
			}
		}
		if (!result.getRunePouch().isEmpty())
		{
			resultPanel.add(Box.createVerticalStrut(4));
			resultPanel.add(header("Rune pouch"));
			for (BuildResult.InventoryPick pick : result.getRunePouch())
			{
				resultPanel.add(itemRow(pick.getItemId(), null, pick.getName(), Color.WHITE));
			}
		}
		if (!result.getUnownedInventory().isEmpty())
		{
			resultPanel.add(smallText("Not owned: " + String.join(", ", result.getUnownedInventory()), MUTED));
		}
		if (!result.getUnresolvedNames().isEmpty())
		{
			resultPanel.add(smallText("Not recognised as items: " + String.join(", ", result.getUnresolvedNames()), MUTED));
		}
		if (result.getPicks().isEmpty() && result.getInventory().isEmpty())
		{
			resultPanel.add(smallText("You own none of the recommended items for this setup.", MUTED));
		}

		actionRow.setVisible(true);
		leftAlign(resultPanel);
		resultPanel.revalidate();
		resultPanel.repaint();
	}

	public void setStatuses(List<TagStatus> statuses)
	{
		currentStatuses = statuses;
		generatedPanel.removeAll();
		if (statuses.isEmpty())
		{
			generatedPanel.add(smallText("No tags generated yet.", MUTED));
		}
		for (TagStatus status : statuses)
		{
			generatedPanel.add(statusRow(status));
			generatedPanel.add(Box.createVerticalStrut(4));
		}
		leftAlign(generatedPanel);
		generatedPanel.revalidate();
		generatedPanel.repaint();
		updateStatusLabel();
	}

	private JPanel statusRow(TagStatus status)
	{
		GeneratedTag g = status.getTag();
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(6, 6, 6, 6));

		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		if (g.getIconItemId() > 0)
		{
			itemManager.getImage(g.getIconItemId()).addTo(icon);
		}
		top.add(icon, BorderLayout.WEST);
		JLabel name = new JLabel("<html><b>" + escape(g.getTag()) + "</b><br>"
			+ "<span style='color:#a0a0a0'>OSRS Wiki, pulled " + formatDate(g.getFetchedAt())
			+ (g.isSourceChanged() ? ". Wiki page updated" : "") + "</span></html>");
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);
		top.add(name, BorderLayout.CENTER);
		row.add(top);

		if (status.isUserEdited())
		{
			row.add(smallText("Edited by you in Bank Tags", UPDATE_COLOR));
		}
		if (status.isUpdateAvailable())
		{
			row.add(smallText("Update available from your last build", UPDATE_COLOR));
			for (String change : status.getChanges())
			{
				row.add(smallText("  " + change, Color.WHITE));
			}
		}

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
		buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		if (status.isUpdateAvailable())
		{
			JButton apply = smallButton("Apply update");
			apply.setToolTipText("Write the result of your last build to this tag");
			apply.addActionListener(e ->
			{
				if (status.isUserEdited())
				{
					int choice = JOptionPane.showConfirmDialog(this,
						"You edited the tag '" + g.getTag() + "' yourself in Bank Tags.\nApplying replaces your edits with the built result. Continue?",
						"Overwrite your edits?", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
					if (choice != JOptionPane.YES_OPTION)
					{
						return;
					}
				}
				plugin.applyUpdate(g.getTag());
			});
			buttons.add(apply);
		}
		JButton copy = smallButton("Copy string");
		copy.addActionListener(e ->
		{
			copyToClipboard(BankTagWriter.exportString(g.getTag(), g.getIconItemId(), g.getItemIds(), new HashSet<>(g.getExactItemIds() == null ? Collections.emptyList() : g.getExactItemIds())));
			setWrapped(statusLabel, "Import string for '" + g.getTag() + "' copied.");
		});
		buttons.add(copy);
		JButton remove = smallButton("Remove");
		remove.addActionListener(e ->
		{
			Object[] options = {"Remove tag from bank too", "Stop tracking only", "Cancel"};
			int choice = JOptionPane.showOptionDialog(this,
				"Stop tracking '" + g.getTag() + "'?",
				"Remove generated tag", JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE, null, options, options[2]);
			if (choice == 0 || choice == 1)
			{
				plugin.removeGenerated(g.getTag(), choice == 0);
			}
		});
		buttons.add(remove);
		row.add(buttons);
		leftAlign(row);
		return row;
	}

	private JPanel itemRow(int itemId, String slot, String text, Color color)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (itemId > 0)
		{
			itemManager.getImage(itemId).addTo(icon);
		}
		row.add(icon, BorderLayout.WEST);
		String html = "<html>" + (slot != null ? "<span style='color:#a0a0a0'>" + escape(slot) + "</span><br>" : "") + escape(text) + "</html>";
		JLabel label = new JLabel(html);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		row.add(label, BorderLayout.CENTER);
		return row;
	}

	private static JLabel header(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(ColorScheme.BRAND_ORANGE);
		label.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		return label;
	}

	private static JLabel smallText(String text, Color color)
	{
		JLabel label = new JLabel("<html>" + escape(text) + "</html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		return label;
	}

	private static JButton smallButton(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		return button;
	}

	/** Wraps text in HTML so long messages wrap inside the narrow side panel. */
	private static void setWrapped(JLabel label, String text)
	{
		label.setText("<html>" + escape(text) + "</html>");
	}

	private static String formatDate(long epochMillis)
	{
		if (epochMillis <= 0)
		{
			return "unknown date";
		}
		return DATE.format(Instant.ofEpochMilli(epochMillis).atZone(ZoneId.systemDefault()));
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.banktaggearbuilder.wiki;

import com.banktaggearbuilder.model.ContentPage;
import com.banktaggearbuilder.model.GearSetup;
import com.banktaggearbuilder.model.StrategyPage;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Data;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.util.Filepath;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Talks to the OSRS Wiki MediaWiki API, with an on-disk cache keyed by the client revision
 * so the wiki is only asked again after a client update (or on an explicit refresh).
 * Callbacks run on a background thread, never the client thread.
 */
@Slf4j
@Singleton
public class WikiClient
{
	private static final HttpUrl API = HttpUrl.parse("https://oldschool.runescape.wiki/api.php");
	/** Names this plugin to the wiki; RuneLite's client prefixes it with its own RuneLite/version agent. */
	private static final String USER_AGENT = "BankTagGearBuilder (+https://github.com/jb1361/bank-tag-gear-builder)";
	private static final String EQUIPMENT_TEMPLATE = "Template:Recommended equipment";
	private static final String COMBAT_ACHIEVEMENTS_CATEGORY = "Category:Combat Achievements";
	private static final String CONTENT_FILE = "content.json";
	private static final String STRATEGIES_SUFFIX = "/Strategies";
	private static final String PAGES_DIR = "pages";
	/**
	 * New content is often released without a client revision change, so the content list
	 * also expires after this long.
	 */
	private static final long CONTENT_MAX_AGE_MS = TimeUnit.DAYS.toMillis(21);

	/** On-disk form of the content list. */
	@Data
	private static class CachedContent
	{
		private int revision;
		private long fetchedAt;
		private List<String> titles = new ArrayList<>();
	}

	/** On-disk form of one parsed strategy page. */
	@Data
	private static class CachedPage
	{
		private int revision;
		private String title;
		private String displayOverride;
		private long revId;
		private long fetchedAt;
		private List<GearSetup> setups = new ArrayList<>();
	}

	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final Client client;
	private final ScheduledExecutorService executor;
	private final WikiTextParser parser = new WikiTextParser();

	/** Directory for the cache, or null when none is available (then every call goes to the wiki). */
	private volatile Filepath cacheDir;

	@Inject
	private WikiClient(OkHttpClient okHttpClient, Gson gson, Client client, ScheduledExecutorService executor)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
		this.client = client;
		this.executor = executor;
	}

	public void setCacheDirectory(Filepath dir)
	{
		this.cacheDir = dir;
	}

	/** The client revision. Content updates often ship without changing it. */
	private int gameRevision()
	{
		return client.getRevision();
	}

	// ---- Content list ----

	/**
	 * Lists every main-namespace page that uses the Recommended equipment template, except
	 * Combat Achievements task pages. Served from the cache unless the game has updated since
	 * it was written, it is older than {@link #CONTENT_MAX_AGE_MS}, or {@code force} is set.
	 */
	public void listContent(boolean force, Consumer<List<ContentPage>> onSuccess, Consumer<String> onError)
	{
		executor.execute(() ->
		{
			Filepath file = cacheFile(CONTENT_FILE);
			if (!force && file != null)
			{
				CachedContent cached = readJson(file, CachedContent.class);
				if (cached != null && isCurrent(cached.getRevision())
					&& System.currentTimeMillis() - cached.getFetchedAt() < CONTENT_MAX_AGE_MS)
				{
					List<ContentPage> pages = new ArrayList<>();
					for (String title : cached.getTitles())
					{
						pages.add(new ContentPage(title));
					}
					// Filtered again so lists cached before a rule change still follow it
					pages = disambiguate(dropDuplicateStrategies(pages));
					log.debug("Content list served from cache (revision {})", cached.getRevision());
					onSuccess.accept(pages);
					return;
				}
			}
			listContentPage(null, new LinkedHashMap<>(), pages ->
			{
				if (file != null)
				{
					CachedContent cached = new CachedContent();
					cached.setRevision(gameRevision());
					cached.setFetchedAt(System.currentTimeMillis());
					for (ContentPage p : pages)
					{
						cached.getTitles().add(p.getTitle());
					}
					writeJson(file, cached);
				}
				onSuccess.accept(pages);
			}, onError);
		});
	}

	/**
	 * Lists pages using the template together with whether each is a Combat Achievements
	 * task page; those are left out since their gear tables describe a single task, not
	 * the content. {@code continuation} carries the API's continue parameters between calls.
	 */
	private void listContentPage(Map<String, String> continuation, Map<String, Boolean> acc, Consumer<List<ContentPage>> onSuccess, Consumer<String> onError)
	{
		HttpUrl.Builder url = API.newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("generator", "embeddedin")
			.addQueryParameter("geititle", EQUIPMENT_TEMPLATE)
			.addQueryParameter("geinamespace", "0")
			.addQueryParameter("geilimit", "500")
			.addQueryParameter("prop", "categories")
			.addQueryParameter("clcategories", COMBAT_ACHIEVEMENTS_CATEGORY)
			.addQueryParameter("cllimit", "500")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2");
		if (continuation != null)
		{
			for (Map.Entry<String, String> e : continuation.entrySet())
			{
				url.addQueryParameter(e.getKey(), e.getValue());
			}
		}

		get(url.build(), onError, json ->
		{
			JsonObject query = json.getAsJsonObject("query");
			JsonArray pages = query == null ? new JsonArray() : query.getAsJsonArray("pages");
			for (JsonElement e : pages)
			{
				JsonObject page = e.getAsJsonObject();
				String title = page.get("title").getAsString();
				boolean combatAchievement = page.has("categories") && page.getAsJsonArray("categories").size() > 0;
				acc.merge(title, combatAchievement, Boolean::logicalOr);
			}
			JsonObject cont = json.getAsJsonObject("continue");
			if (cont != null)
			{
				Map<String, String> next = new HashMap<>();
				for (Map.Entry<String, JsonElement> e : cont.entrySet())
				{
					next.put(e.getKey(), e.getValue().getAsString());
				}
				listContentPage(next, acc, onSuccess, onError);
				return;
			}
			List<ContentPage> result = new ArrayList<>();
			for (Map.Entry<String, Boolean> e : acc.entrySet())
			{
				if (!e.getValue())
				{
					result.add(new ContentPage(e.getKey()));
				}
			}
			result = disambiguate(dropDuplicateStrategies(result));
			result.sort(Comparator.comparing(p -> p.getDisplayName().toLowerCase()));
			onSuccess.accept(result);
		});
	}

	/**
	 * Drops a "/Strategies" page when another page has the same short name, e.g.
	 * "Chambers of Xeric/Challenge Mode/Strategies" beside "Chambers of Xeric/Challenge Mode".
	 */
	private static List<ContentPage> dropDuplicateStrategies(List<ContentPage> pages)
	{
		Set<String> plainNames = new HashSet<>();
		for (ContentPage p : pages)
		{
			if (!p.getTitle().endsWith(STRATEGIES_SUFFIX))
			{
				plainNames.add(ContentPage.shortName(p.getTitle()));
			}
		}
		List<ContentPage> out = new ArrayList<>(pages.size());
		for (ContentPage p : pages)
		{
			if (!p.getTitle().endsWith(STRATEGIES_SUFFIX) || !plainNames.contains(ContentPage.shortName(p.getTitle())))
			{
				out.add(p);
			}
		}
		return out;
	}

	/**
	 * Pages whose short names still collide are shown with their full page path.
	 */
	private static List<ContentPage> disambiguate(List<ContentPage> pages)
	{
		Map<String, Integer> counts = new HashMap<>();
		for (ContentPage p : pages)
		{
			counts.merge(p.getDisplayName(), 1, Integer::sum);
		}
		List<ContentPage> out = new ArrayList<>(pages.size());
		for (ContentPage p : pages)
		{
			if (counts.get(p.getDisplayName()) > 1)
			{
				out.add(new ContentPage(p.getTitle(), p.getTitle().replace("/", " / ")));
			}
			else
			{
				out.add(p);
			}
		}
		return out;
	}

	// ---- Strategy pages ----

	/**
	 * Fetches and parses a strategy page. Served from the cache unless the game has updated
	 * since the page was written, or {@code force} is set.
	 */
	public void fetchStrategy(ContentPage page, boolean force, Consumer<StrategyPage> onSuccess, Consumer<String> onError)
	{
		executor.execute(() ->
		{
			Filepath file = cacheFile(PAGES_DIR + "/" + fileNameFor(page.getTitle()));
			if (!force && file != null)
			{
				CachedPage cached = readJson(file, CachedPage.class);
				if (cached != null && isCurrent(cached.getRevision()) && cached.getSetups() != null && !cached.getSetups().isEmpty())
				{
					log.debug("{} served from cache (revision {})", page.getTitle(), cached.getRevision());
					onSuccess.accept(new StrategyPage(page, cached.getRevId(), cached.getFetchedAt(), cached.getSetups()));
					return;
				}
			}
			fetchStrategyFromWiki(page, sp ->
			{
				if (file != null)
				{
					CachedPage cached = new CachedPage();
					cached.setRevision(gameRevision());
					cached.setTitle(page.getTitle());
					cached.setDisplayOverride(page.getDisplayOverride());
					cached.setRevId(sp.getRevId());
					cached.setFetchedAt(sp.getFetchedAt());
					cached.setSetups(sp.getSetups());
					writeJson(file, cached);
				}
				onSuccess.accept(sp);
			}, onError);
		});
	}

	private void fetchStrategyFromWiki(ContentPage page, Consumer<StrategyPage> onSuccess, Consumer<String> onError)
	{
		HttpUrl url = API.newBuilder()
			.addQueryParameter("action", "parse")
			.addQueryParameter("page", page.getTitle())
			.addQueryParameter("prop", "wikitext|revid")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();

		get(url, onError, json ->
		{
			JsonObject parse = json.getAsJsonObject("parse");
			if (parse == null)
			{
				onError.accept("Wiki page not found: " + page.getTitle());
				return;
			}
			String wikitext = parse.get("wikitext").getAsString();
			long revId = parse.has("revid") ? parse.get("revid").getAsLong() : 0;
			List<GearSetup> setups = parser.parse(wikitext);
			if (setups.isEmpty())
			{
				onError.accept("No recommended equipment table found on " + page.getTitle());
				return;
			}
			onSuccess.accept(new StrategyPage(page, revId, System.currentTimeMillis(), setups));
		});
	}

	// ---- Cache files ----

	/** A cache entry is current when it was written for the game revision now running. */
	private boolean isCurrent(int cachedRevision)
	{
		int now = gameRevision();
		// Before the game cache is known, keep whatever is cached rather than pounding the wiki
		return now <= 0 || cachedRevision == now;
	}

	private Filepath cacheFile(String relative)
	{
		Filepath dir = cacheDir;
		if (dir == null)
		{
			return null;
		}
		String[] parts = relative.split("/");
		Filepath f = dir;
		for (String part : parts)
		{
			f = f.joinSegment(part);
		}
		return f;
	}

	/** Title turned into a safe file name, with a hash so similar titles never collide. */
	private static String fileNameFor(String title)
	{
		String safe = title.replaceAll("[^A-Za-z0-9._-]", "_");
		if (safe.length() > 80)
		{
			safe = safe.substring(0, 80);
		}
		return safe + "-" + Integer.toHexString(title.hashCode()) + ".json";
	}

	private <T> T readJson(Filepath file, Class<T> type)
	{
		try
		{
			if (!file.isFile())
			{
				return null;
			}
			try (Reader reader = file.openBufferedReader())
			{
				return gson.fromJson(reader, type);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not read cache file {}", file, e);
			return null;
		}
	}

	private void writeJson(Filepath file, Object value)
	{
		try
		{
			Filepath parent = file.getParent();
			if (parent != null)
			{
				parent.createDirectories();
			}
			file.write(gson.toJson(value));
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not write cache file {}", file, e);
		}
	}

	// ---- HTTP ----

	private void get(HttpUrl url, Consumer<String> onError, Consumer<JsonObject> onJson)
	{
		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Wiki request failed: {}", url, e);
				onError.accept("Could not reach the OSRS Wiki: " + e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						onError.accept("Wiki returned HTTP " + r.code());
						return;
					}
					JsonObject json = gson.fromJson(r.body().charStream(), JsonObject.class);
					if (json.has("error"))
					{
						onError.accept("Wiki error: " + json.getAsJsonObject("error").get("info").getAsString());
						return;
					}
					onJson.accept(json);
				}
				catch (Exception e)
				{
					log.debug("Failed to parse wiki response from {}", url, e);
					onError.accept("Could not read the wiki response: " + e.getMessage());
				}
			}
		});
	}
}

package com.banktaggearbuilder.wiki;

import com.banktaggearbuilder.model.Alternative;
import com.banktaggearbuilder.model.EquipmentSlot;
import com.banktaggearbuilder.model.GearSetup;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * Extracts {@code {{Recommended equipment}}}, {@code {{Inventory}}} and {@code {{Rune pouch}}}
 * templates from the wikitext of an OSRS Wiki strategy page.
 */
public class WikiTextParser
{
	private static final Pattern SLOT_PARAM = Pattern.compile("^(head|neck|cape|body|legs|weapon|2h|shield|ammo|hands|feet|ring|special)([1-5])$");
	private static final Pattern BR = Pattern.compile("(?i)<\\s*/?\\s*br\\s*/?\\s*>");
	private static final Pattern BR_AFTER_JOIN = Pattern.compile("(?i)(\\+|\\band)\\s*<\\s*/?\\s*br\\s*/?\\s*>\\s*");
	private static final Pattern BR_BEFORE_JOIN = Pattern.compile("(?i)<\\s*/?\\s*br\\s*/?\\s*>\\s*(\\+|and\\b)");
	private static final Pattern REF = Pattern.compile("(?is)<ref[^>]*/>|<ref[^>]*>.*?</ref>");
	private static final Pattern COMMENT = Pattern.compile("(?s)<!--.*?-->");
	private static final Pattern HTML_TAG = Pattern.compile("<[^>]+>");
	private static final Pattern WIKILINK = Pattern.compile("\\[\\[([^\\]|]+)(?:\\|[^\\]]*)?\\]\\]");
	private static final Pattern TABBER_LABEL = Pattern.compile("(?m)^\\s*([^=\\n|]+?)\\s*=\\s*$");
	private static final Pattern HEADING = Pattern.compile("(?m)^(={2,6})\\s*(.+?)\\s*\\1\\s*$");

	/**
	 * Wiki templates that stand in for "any cheap X". Listed best-first.
	 */
	private static final Map<String, List<String>> PSEUDO_ITEMS = new HashMap<>();

	static
	{
		PSEUDO_ITEMS.put("cheap food", Arrays.asList("Shark", "Manta ray", "Anglerfish", "Dark crab", "Sea turtle",
			"Monkfish", "Cooked karambwan", "Lobster", "Swordfish", "Tuna"));
		PSEUDO_ITEMS.put("cheap prayer", Arrays.asList("Prayer potion(4)", "Super restore(4)"));
		PSEUDO_ITEMS.put("cheap prayer potion", Arrays.asList("Prayer potion(4)", "Super restore(4)"));
		PSEUDO_ITEMS.put("cheap teleport", Arrays.asList("Teleport to house", "Varrock teleport", "Ring of dueling(8)",
			"Games necklace(8)", "Amulet of glory(6)"));
	}

	@Value
	private static class Template
	{
		String name;
		Map<String, String> params;
		int start;
		int end;
	}

	@Value
	private static class InventoryBlock
	{
		String label;
		List<List<String>> entries;
		List<List<String>> runePouch;
		/** True when this block is the union of several unlabelled example loadouts. */
		boolean fromTiers;
	}

	/** A wikitable: column headers and rows of raw cell text. */
	@Value
	private static class WikiTable
	{
		List<String> headers;
		List<List<String>> rows;
		int start;
		int end;
	}

	public List<GearSetup> parse(String wikitext)
	{
		String text = COMMENT.matcher(wikitext).replaceAll("");
		List<Template> headings = findHeadings(text);
		List<GearSetup> setups = new ArrayList<>();

		for (Template t : findTemplates(text, "recommended equipment"))
		{
			GearSetup setup = new GearSetup();
			setup.setStyle(cleanText(t.getParams().getOrDefault("style", "")));
			// Tables in the page's top-level Equipment section all belong together even when a
			// sub-heading (e.g. "Scythe considerations") sits between them
			String top = topSectionFor(headings, t.getStart());
			setup.setSection(top.equalsIgnoreCase("equipment") ? top : sectionFor(headings, t.getStart()));
			for (Map.Entry<String, String> e : t.getParams().entrySet())
			{
				Matcher m = SLOT_PARAM.matcher(e.getKey());
				if (!m.matches())
				{
					continue;
				}
				EquipmentSlot slot = EquipmentSlot.fromWikiParam(m.group(1));
				int rank = Integer.parseInt(m.group(2));
				List<Alternative> alternatives = parseAlternatives(e.getValue());
				if (slot != null && !alternatives.isEmpty())
				{
					setup.addRank(slot, rank, alternatives);
				}
			}
			if (!setup.isEmpty())
			{
				setups.add(setup);
			}
		}

		// A page with a top-level Equipment section lists its real loadouts there; tables
		// further down (per boss or phase) are partial and would only add duplicate gear
		boolean hasEquipmentSection = setups.stream().anyMatch(s -> s.getSection().equalsIgnoreCase("equipment"));
		if (hasEquipmentSection)
		{
			setups.removeIf(s -> !s.getSection().equalsIgnoreCase("equipment"));
		}

		List<InventoryBlock> inventories = findInventories(text);
		for (GearSetup setup : setups)
		{
			InventoryBlock inv = matchInventory(setup.getStyle(), inventories);
			if (inv != null)
			{
				setup.setInventory(inv.getEntries());
				setup.setRunePouch(inv.getRunePouch());
				setup.setInventoryFromTiers(inv.isFromTiers());
			}
		}

		return addCombined(setups);
	}

	/**
	 * Where a section holds several combat-style tables (melee, ranged and magic for a raid,
	 * for example), adds a combined setup that builds all of them into one tag. Tables named
	 * after a tier or mode ("Learner", "Entry mode") are left out of the combination.
	 */
	private static List<GearSetup> addCombined(List<GearSetup> setups)
	{
		Map<String, List<GearSetup>> bySection = new LinkedHashMap<>();
		for (GearSetup s : setups)
		{
			bySection.computeIfAbsent(s.getSection(), k -> new ArrayList<>()).add(s);
		}

		List<GearSetup> out = new ArrayList<>();
		for (Map.Entry<String, List<GearSetup>> e : bySection.entrySet())
		{
			List<GearSetup> group = e.getValue();
			List<GearSetup> styled = new ArrayList<>();
			for (GearSetup s : group)
			{
				if (isCombatStyle(s.getStyle()))
				{
					styled.add(s);
				}
			}
			if (styled.size() > 1)
			{
				GearSetup combined = new GearSetup();
				combined.setSection(e.getKey());
				List<String> styles = new ArrayList<>();
				for (GearSetup s : styled)
				{
					styles.add(s.getStyle());
				}
				combined.setStyle("All (" + String.join(" + ", styles) + ")");
				combined.setComponents(new ArrayList<>(styled));
				combined.setInventory(union(styled, true));
				combined.setRunePouch(union(styled, false));
				combined.setInventoryFromTiers(styled.stream().anyMatch(GearSetup::isInventoryFromTiers));
				out.add(combined);
			}
			out.addAll(group);
		}
		return out;
	}

	private static boolean isCombatStyle(String style)
	{
		String n = normalize(style);
		return n.contains("melee") || n.contains("range") || n.contains("mage");
	}

	private static List<List<String>> union(List<GearSetup> setups, boolean inventory)
	{
		Map<String, List<String>> unique = new LinkedHashMap<>();
		for (GearSetup s : setups)
		{
			for (List<String> names : inventory ? s.getInventory() : s.getRunePouch())
			{
				unique.putIfAbsent(names.get(0).toLowerCase(Locale.ROOT), names);
			}
		}
		return new ArrayList<>(unique.values());
	}

	/**
	 * Splits a slot value such as {@code {{plink|A}} / {{plink|B|pic=C}}{{efn|...}}} into
	 * alternatives. Items joined with "+" or "and" form one alternative with several items.
	 */
	List<Alternative> parseAlternatives(String value)
	{
		String v = removeTemplates(value, "efn");
		v = REF.matcher(v).replaceAll("");
		// A line break next to "+" or "and" is just wrapping, not a new alternative
		v = BR_AFTER_JOIN.matcher(v).replaceAll("$1 ");
		v = BR_BEFORE_JOIN.matcher(v).replaceAll(" $1");
		v = BR.matcher(v).replaceAll(" / ");
		v = replaceTopLevelWord(v, "and", "+");

		List<Alternative> alternatives = new ArrayList<>();
		for (String piece : splitTopLevel(v, "/>"))
		{
			Alternative alternative = new Alternative();
			for (String part : splitTopLevel(piece, "+"))
			{
				List<String> names = extractNames(part);
				if (!names.isEmpty())
				{
					alternative.getItems().add(names);
				}
			}
			if (!alternative.getItems().isEmpty())
			{
				alternatives.add(alternative);
			}
		}
		return alternatives;
	}

	private List<String> extractNames(String piece)
	{
		List<String> names = new ArrayList<>();
		for (Template t : findTemplates(piece, null))
		{
			String name = t.getName();
			if (name.equals("plink") || name.equals("plinkp") || name.equals("plinkt") || name.equals("plinkk"))
			{
				String page = cleanText(t.getParams().getOrDefault("1", ""));
				if (!page.isEmpty())
				{
					names.add(page);
				}
				String pic = cleanText(t.getParams().getOrDefault("pic", ""));
				if (!pic.isEmpty() && !pic.equalsIgnoreCase(page))
				{
					names.add(pic);
				}
			}
			else if (PSEUDO_ITEMS.containsKey(name))
			{
				names.addAll(PSEUDO_ITEMS.get(name));
			}
		}
		if (!names.isEmpty())
		{
			return names;
		}

		Matcher link = WIKILINK.matcher(piece);
		if (link.find())
		{
			String page = cleanText(link.group(1));
			if (!page.isEmpty())
			{
				names.add(page);
			}
			return names;
		}

		String plain = cleanText(removeTemplates(piece, null));
		if (!plain.isEmpty() && !plain.equalsIgnoreCase("n/a") && !plain.equalsIgnoreCase("none")
			&& !plain.toLowerCase(Locale.ROOT).startsWith("see "))
		{
			names.add(plain);
		}
		return names;
	}

	// ---- Inventories ----

	/**
	 * Collects every inventory on the page with the best label available: the column header
	 * for inventories in a table of example loadouts, the tab name for ones inside a tabber,
	 * and no label otherwise.
	 */
	private List<InventoryBlock> findInventories(String text)
	{
		List<InventoryBlock> blocks = new ArrayList<>();

		List<WikiTable> tables = findTables(text);
		for (WikiTable table : tables)
		{
			blocks.addAll(blocksFromTable(table));
		}

		// Look at the rest of the page with the tables blanked out so nothing is counted twice
		StringBuilder rest = new StringBuilder(text);
		for (WikiTable table : tables)
		{
			for (int i = table.getStart(); i < table.getEnd(); i++)
			{
				rest.setCharAt(i, ' ');
			}
		}
		String remaining = rest.toString();

		String lower = remaining.toLowerCase(Locale.ROOT);
		int idx = 0;
		boolean sawTabber = false;
		while (true)
		{
			int open = lower.indexOf("<tabber>", idx);
			if (open < 0)
			{
				break;
			}
			sawTabber = true;
			int close = lower.indexOf("</tabber>", open);
			if (close < 0)
			{
				close = remaining.length();
			}
			String inner = remaining.substring(open + "<tabber>".length(), close);
			for (String tab : inner.split("\\|-\\|"))
			{
				String label = "";
				Matcher m = TABBER_LABEL.matcher(tab);
				if (m.find())
				{
					label = m.group(1).trim();
				}
				addBlock(blocks, label, tab);
			}
			idx = close;
		}

		if (blocks.isEmpty() || !sawTabber)
		{
			addBlock(blocks, "", remaining);
		}
		return blocks;
	}

	/** Adds one block per inventory (with the section's rune pouch, if any) found in {@code section}. */
	private void addBlock(List<InventoryBlock> blocks, String label, String section)
	{
		List<Template> inventories = findTemplates(section, "inventory");
		List<Template> pouches = findTemplates(section, "rune pouch");
		if (inventories.isEmpty())
		{
			if (!pouches.isEmpty())
			{
				blocks.add(new InventoryBlock(label, new ArrayList<>(), runeEntries(pouches.get(0)), false));
			}
			return;
		}
		for (int i = 0; i < inventories.size(); i++)
		{
			// Pair the i-th inventory with the i-th pouch when a section lists several of each,
			// otherwise share the only pouch
			Template pouch = pouches.isEmpty() ? null : pouches.get(Math.min(i, pouches.size() - 1));
			blocks.add(new InventoryBlock(label, inventoryEntries(inventories.get(i)),
				pouch == null ? new ArrayList<>() : runeEntries(pouch), false));
		}
	}

	/** One block per table column that holds an inventory or rune pouch, labelled by its header. */
	private List<InventoryBlock> blocksFromTable(WikiTable table)
	{
		int columns = table.getHeaders().size();
		for (List<String> row : table.getRows())
		{
			columns = Math.max(columns, row.size());
		}

		List<InventoryBlock> blocks = new ArrayList<>();
		for (int c = 0; c < columns; c++)
		{
			Template inventory = null;
			Template pouch = null;
			for (List<String> row : table.getRows())
			{
				if (c >= row.size())
				{
					continue;
				}
				String cell = row.get(c);
				if (inventory == null)
				{
					List<Template> found = findTemplates(cell, "inventory");
					inventory = found.isEmpty() ? null : found.get(0);
				}
				if (pouch == null)
				{
					List<Template> found = findTemplates(cell, "rune pouch");
					pouch = found.isEmpty() ? null : found.get(0);
				}
			}
			if (inventory == null && pouch == null)
			{
				continue;
			}
			String label = c < table.getHeaders().size() ? table.getHeaders().get(c) : "";
			blocks.add(new InventoryBlock(label,
				inventory == null ? new ArrayList<>() : inventoryEntries(inventory),
				pouch == null ? new ArrayList<>() : runeEntries(pouch), false));
		}
		return blocks;
	}

	private List<List<String>> inventoryEntries(Template inventory)
	{
		Map<String, List<String>> unique = new LinkedHashMap<>();
		for (int i = 1; i <= 28; i++)
		{
			String value = inventory.getParams().get(String.valueOf(i));
			if (value == null || value.trim().isEmpty())
			{
				continue;
			}
			List<Alternative> alternatives = parseAlternatives(value);
			if (alternatives.isEmpty())
			{
				continue;
			}
			List<String> names = alternatives.get(0).getItems().get(0);
			unique.putIfAbsent(names.get(0).toLowerCase(Locale.ROOT), names);
		}
		return new ArrayList<>(unique.values());
	}

	private List<List<String>> runeEntries(Template pouch)
	{
		Map<String, List<String>> unique = new LinkedHashMap<>();
		for (int i = 1; i <= 4; i++)
		{
			String value = pouch.getParams().get(String.valueOf(i));
			if (value == null || value.trim().isEmpty())
			{
				continue;
			}
			List<Alternative> alternatives = parseAlternatives(value);
			if (!alternatives.isEmpty())
			{
				List<String> names = alternatives.get(0).getItems().get(0);
				unique.putIfAbsent(names.get(0).toLowerCase(Locale.ROOT), names);
			}
		}
		return new ArrayList<>(unique.values());
	}

	/**
	 * Picks the inventory for a style: an exact or partial label match ("Melee" matches
	 * "Melee Role", "Magic" matches "Mage/Freezer Role"), the only inventory if there is one,
	 * or, when a page lists several inventories that are not labelled by style (a table of
	 * example tiers), the union of all of them.
	 */
	private InventoryBlock matchInventory(String style, List<InventoryBlock> inventories)
	{
		if (inventories.isEmpty())
		{
			return null;
		}
		String want = normalize(style);
		for (InventoryBlock b : inventories)
		{
			if (normalize(b.getLabel()).equals(want))
			{
				return b;
			}
		}
		if (!want.isEmpty())
		{
			for (InventoryBlock b : inventories)
			{
				String have = normalize(b.getLabel());
				if (!have.isEmpty() && (have.contains(want) || want.contains(have)))
				{
					return b;
				}
			}
		}
		if (inventories.size() == 1)
		{
			return inventories.get(0);
		}

		Map<String, List<String>> entries = new LinkedHashMap<>();
		Map<String, List<String>> runes = new LinkedHashMap<>();
		for (InventoryBlock b : inventories)
		{
			for (List<String> names : b.getEntries())
			{
				entries.putIfAbsent(names.get(0).toLowerCase(Locale.ROOT), names);
			}
			for (List<String> names : b.getRunePouch())
			{
				runes.putIfAbsent(names.get(0).toLowerCase(Locale.ROOT), names);
			}
		}
		return new InventoryBlock("", new ArrayList<>(entries.values()), new ArrayList<>(runes.values()), true);
	}

	/** Lower-case alphanumerics only, with "magic" and "ranged" folded to "mage" and "range". */
	private static String normalize(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.toLowerCase(Locale.ROOT)
			.replace("magic", "mage")
			.replace("ranged", "range")
			.replaceAll("[^a-z0-9]", "");
	}

	// ---- Tables ----

	/**
	 * Parses every top-level wikitable ({@code {| ... |}}). Cells are split only where a
	 * {@code |}, {@code ||}, {@code !} or {@code !!} occurs outside a template, so a template's
	 * own parameter lines inside a cell are kept with it.
	 */
	private static List<WikiTable> findTables(String text)
	{
		List<WikiTable> tables = new ArrayList<>();
		int idx = 0;
		while (true)
		{
			int start = indexOfLineStart(text, "{|", idx);
			if (start < 0)
			{
				break;
			}
			int end = findTableEnd(text, start);
			if (end < 0)
			{
				break;
			}
			tables.add(parseTable(text.substring(start, end), start, end));
			idx = end;
		}
		return tables;
	}

	/** Index of {@code needle} at the start of a line at or after {@code from}, or -1. */
	private static int indexOfLineStart(String text, String needle, int from)
	{
		int i = text.indexOf(needle, from);
		while (i >= 0)
		{
			if (i == 0 || text.charAt(i - 1) == '\n')
			{
				return i;
			}
			i = text.indexOf(needle, i + 1);
		}
		return -1;
	}

	/** Index just past the {@code |}} closing the table opened at {@code start}, nested tables included. */
	private static int findTableEnd(String text, int start)
	{
		int depth = 0;
		int i = start;
		while (i < text.length())
		{
			int lineEnd = text.indexOf('\n', i);
			if (lineEnd < 0)
			{
				lineEnd = text.length();
			}
			String line = text.substring(i, lineEnd).trim();
			if (line.startsWith("{|"))
			{
				depth++;
			}
			else if (line.startsWith("|}"))
			{
				depth--;
				if (depth == 0)
				{
					return lineEnd;
				}
			}
			i = lineEnd + 1;
		}
		return -1;
	}

	private static WikiTable parseTable(String table, int start, int end)
	{
		List<String> headers = new ArrayList<>();
		List<List<String>> rows = new ArrayList<>();
		List<String> row = new ArrayList<>();
		StringBuilder cell = null;
		boolean cellIsHeader = false;
		int depth = 0;

		String[] lines = table.split("\n");
		for (int li = 1; li < lines.length; li++)
		{
			String line = lines[li];
			String trimmed = line.trim();
			if (depth == 0 && (trimmed.startsWith("|}") || trimmed.startsWith("|+")))
			{
				continue;
			}
			if (depth == 0 && trimmed.startsWith("|-"))
			{
				if (cell != null)
				{
					finishCell(cell, cellIsHeader, headers, row);
					cell = null;
				}
				if (!row.isEmpty())
				{
					rows.add(row);
					row = new ArrayList<>();
				}
				continue;
			}
			if (depth == 0 && (trimmed.startsWith("|") || trimmed.startsWith("!")))
			{
				boolean header = trimmed.startsWith("!");
				String rest = trimmed.substring(1);
				List<String> parts = splitTopLevelString(rest, header ? "!!" : "||");
				for (int p = 0; p < parts.size(); p++)
				{
					if (cell != null)
					{
						finishCell(cell, cellIsHeader, headers, row);
					}
					cell = new StringBuilder(parts.get(p));
					cellIsHeader = header;
				}
			}
			else if (cell != null)
			{
				cell.append('\n').append(line);
			}
			depth += count(line, "{{") - count(line, "}}");
			if (depth < 0)
			{
				depth = 0;
			}
		}
		if (cell != null)
		{
			finishCell(cell, cellIsHeader, headers, row);
		}
		if (!row.isEmpty())
		{
			rows.add(row);
		}
		return new WikiTable(headers, rows, start, end);
	}

	private static void finishCell(StringBuilder cell, boolean header, List<String> headers, List<String> row)
	{
		String content = cell.toString();
		if (header)
		{
			// "colspan=2 | Label" keeps the text after the attribute separator; first line only
			String label = content;
			int bar = label.indexOf('|');
			if (bar >= 0 && label.lastIndexOf("{{", bar) < 0 && label.lastIndexOf("[[", bar) < 0)
			{
				label = label.substring(bar + 1);
			}
			int nl = label.indexOf('\n');
			if (nl >= 0)
			{
				label = label.substring(0, nl);
			}
			headers.add(cleanText(label));
		}
		else
		{
			row.add(content);
		}
	}

	private static List<String> splitTopLevelString(String s, String separator)
	{
		List<String> parts = new ArrayList<>();
		int depth = 0;
		int last = 0;
		for (int i = 0; i < s.length(); i++)
		{
			if (s.startsWith("{{", i))
			{
				depth++;
				i++;
			}
			else if (s.startsWith("}}", i))
			{
				depth--;
				i++;
			}
			else if (depth == 0 && s.startsWith(separator, i))
			{
				parts.add(s.substring(last, i));
				i += separator.length() - 1;
				last = i + 1;
			}
		}
		parts.add(s.substring(last));
		return parts;
	}

	private static int count(String s, String needle)
	{
		int n = 0;
		int i = s.indexOf(needle);
		while (i >= 0)
		{
			n++;
			i = s.indexOf(needle, i + needle.length());
		}
		return n;
	}

	// ---- Headings ----

	/** Headings as pseudo-templates: name = heading text, params holds the level. */
	private static List<Template> findHeadings(String text)
	{
		List<Template> out = new ArrayList<>();
		Matcher m = HEADING.matcher(text);
		while (m.find())
		{
			Map<String, String> params = new HashMap<>();
			params.put("level", String.valueOf(m.group(1).length()));
			out.add(new Template(cleanText(m.group(2)), params, m.start(), m.end()));
		}
		return out;
	}

	/** The nearest level-2 ("== ... ==") heading above a position, or "" if none. */
	private static String topSectionFor(List<Template> headings, int position)
	{
		String top = "";
		for (Template h : headings)
		{
			if (h.getStart() >= position)
			{
				break;
			}
			if (Integer.parseInt(h.getParams().get("level")) == 2)
			{
				top = h.getName();
			}
		}
		return top;
	}

	/**
	 * The heading a position sits under. A generic "Equipment" sub-heading is replaced by the
	 * heading it belongs to so a boss's equipment table is labelled with the boss.
	 */
	private static String sectionFor(List<Template> headings, int position)
	{
		Template nearest = null;
		for (Template h : headings)
		{
			if (h.getStart() < position)
			{
				nearest = h;
			}
		}
		if (nearest == null)
		{
			return "";
		}
		if (nearest.getName().equalsIgnoreCase("equipment") && Integer.parseInt(nearest.getParams().get("level")) > 2)
		{
			// Walk back to the heading this one belongs to: a sibling or parent, skipping deeper ones
			int level = Integer.parseInt(nearest.getParams().get("level"));
			for (int i = headings.indexOf(nearest) - 1; i >= 0; i--)
			{
				if (Integer.parseInt(headings.get(i).getParams().get("level")) <= level)
				{
					return headings.get(i).getName();
				}
			}
		}
		return nearest.getName();
	}

	// ---- Templates and text ----

	/**
	 * Finds templates in {@code text}. If {@code name} is non-null only templates with that
	 * (case-insensitive) name are returned, including ones nested inside other templates.
	 */
	private static List<Template> findTemplates(String text, String name)
	{
		List<Template> out = new ArrayList<>();
		int i = 0;
		while (i < text.length() - 1)
		{
			if (text.charAt(i) == '{' && text.charAt(i + 1) == '{')
			{
				int end = findTemplateEnd(text, i);
				if (end < 0)
				{
					break;
				}
				String body = text.substring(i + 2, end - 2);
				List<String> parts = splitTopLevel(body, "|");
				String tname = parts.isEmpty() ? "" : parts.get(0).trim().toLowerCase(Locale.ROOT);
				if (name == null || tname.equals(name))
				{
					Map<String, String> params = new LinkedHashMap<>();
					int positional = 1;
					for (int p = 1; p < parts.size(); p++)
					{
						String part = parts.get(p);
						int eq = part.indexOf('=');
						// A '=' inside a nested template or link does not make this a named parameter
						if (eq >= 0 && depthAt(part, eq) == 0)
						{
							params.put(part.substring(0, eq).trim().toLowerCase(Locale.ROOT), part.substring(eq + 1).trim());
						}
						else
						{
							params.put(String.valueOf(positional++), part.trim());
						}
					}
					out.add(new Template(tname, params, i, end));
				}
				else
				{
					for (Template nested : findTemplates(body, name))
					{
						out.add(new Template(nested.getName(), nested.getParams(), nested.getStart() + i + 2, nested.getEnd() + i + 2));
					}
				}
				i = end;
			}
			else
			{
				i++;
			}
		}
		return out;
	}

	/** Returns the index just past the closing braces of the template starting at {@code start}, or -1. */
	private static int findTemplateEnd(String text, int start)
	{
		int depth = 0;
		for (int i = start; i < text.length() - 1; i++)
		{
			char c = text.charAt(i);
			char n = text.charAt(i + 1);
			if (c == '{' && n == '{')
			{
				depth++;
				i++;
			}
			else if (c == '}' && n == '}')
			{
				depth--;
				i++;
				if (depth == 0)
				{
					return i + 1;
				}
			}
		}
		return -1;
	}

	private static int depthAt(String s, int index)
	{
		int depth = 0;
		for (int i = 0; i < index && i < s.length() - 1; i++)
		{
			char c = s.charAt(i);
			char n = s.charAt(i + 1);
			if ((c == '{' && n == '{') || (c == '[' && n == '['))
			{
				depth++;
				i++;
			}
			else if ((c == '}' && n == '}') || (c == ']' && n == ']'))
			{
				depth--;
				i++;
			}
		}
		return depth;
	}

	/** Splits on any of {@code separators} that occur outside templates and links. */
	private static List<String> splitTopLevel(String s, String separators)
	{
		List<String> parts = new ArrayList<>();
		StringBuilder cur = new StringBuilder();
		int depth = 0;
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			char n = i + 1 < s.length() ? s.charAt(i + 1) : '\0';
			if ((c == '{' && n == '{') || (c == '[' && n == '['))
			{
				depth++;
				cur.append(c).append(n);
				i++;
			}
			else if ((c == '}' && n == '}') || (c == ']' && n == ']'))
			{
				depth--;
				cur.append(c).append(n);
				i++;
			}
			else if (depth == 0 && separators.indexOf(c) >= 0)
			{
				parts.add(cur.toString());
				cur.setLength(0);
			}
			else
			{
				cur.append(c);
			}
		}
		parts.add(cur.toString());
		return parts;
	}

	/**
	 * Replaces a whole word that occurs outside templates and links (so "Pestle and mortar"
	 * inside a plink is left alone) with {@code replacement}.
	 */
	private static String replaceTopLevelWord(String s, String word, String replacement)
	{
		StringBuilder out = new StringBuilder(s.length());
		int depth = 0;
		int i = 0;
		while (i < s.length())
		{
			char c = s.charAt(i);
			char n = i + 1 < s.length() ? s.charAt(i + 1) : '\0';
			if ((c == '{' && n == '{') || (c == '[' && n == '['))
			{
				depth++;
				out.append(c).append(n);
				i += 2;
				continue;
			}
			if ((c == '}' && n == '}') || (c == ']' && n == ']'))
			{
				depth--;
				out.append(c).append(n);
				i += 2;
				continue;
			}
			if (depth == 0 && s.regionMatches(true, i, word, 0, word.length())
				&& (i == 0 || Character.isWhitespace(s.charAt(i - 1)))
				&& (i + word.length() >= s.length() || Character.isWhitespace(s.charAt(i + word.length()))))
			{
				out.append(replacement);
				i += word.length();
				continue;
			}
			out.append(c);
			i++;
		}
		return out.toString();
	}

	/** Removes templates named {@code name}, or every top-level template when {@code name} is null. */
	private static String removeTemplates(String s, String name)
	{
		List<Template> found = findTemplates(s, name);
		if (found.isEmpty())
		{
			return s;
		}
		StringBuilder sb = new StringBuilder(s);
		Collections.reverse(found);
		for (Template t : found)
		{
			sb.delete(t.getStart(), t.getEnd());
		}
		return sb.toString();
	}

	private static String cleanText(String s)
	{
		String out = WIKILINK.matcher(s).replaceAll("$1");
		out = HTML_TAG.matcher(out).replaceAll("");
		out = out.replace("'''", "").replace("''", "").replace("&nbsp;", " ");
		return out.trim().replaceAll("\\s+", " ");
	}
}

